root.append(style);
// Integration shell only. The evaluator and modes are generated from calculator-reference.html.
const hostDocument = root.ownerDocument;
const window = {}; // HGL's one-time wiring flags belong to this instance, not the application.
const document = {
  getElementById: id => root.getElementById(id),
  querySelector: selector => root.querySelector(selector),
  querySelectorAll: selector => root.querySelectorAll(selector),
  addEventListener: (...args) => root.addEventListener(...args),
  createElement: tag => hostDocument.createElement(tag),
  execCommand: command => hostDocument.execCommand(command),
  body: root.querySelector('#calc-p'), documentElement: root.host
};
function scheduleAutosave() {} // Lesson utilities are session memory, never authored data or storage.
function autosaveOnStrokeCommit() {}
function showToast(message) { callbacks.status?.(String(message)); }
function toast(message) { showToast(message); }
function togCalc() { callbacks.close(); }
root.addEventListener('keydown',event=>{
  // The chooser covers the expression editor; its keys must not reach that editor.
  if(olmPicker&&!['Tab','Escape'].includes(event.key)){event.stopImmediatePropagation();return;}
  if(event.key==='Delete'&&CALC_STATE.mode==='calculate'&&!event.target.matches('input,textarea')){
    event.preventDefault();event.stopImmediatePropagation();calcInputBackspace();_afterInput();
  }
});

/* ==== src/js/features/calc/calc-core.js ==== */
/* features/calc/calc-core.js — Expression evaluator for HGL calculator
   Lightweight shunting-yard + RPN evaluator supporting:
     - binary ops: + - * / ^; postfix percentage: %
     - unary prefix: -
     - functions: sin cos tan asin acos atan sinh cosh tanh log ln exp sqrt
                  abs round floor ceil gcd lcm min max
     - constants: pi e
     - variables: A..F, x, y, z, M, Ans (stored in CALC_STATE.vars)
     - grouping: ( )
     - factorial postfix: !
   Not a full math.js — we don't need matrices/complex yet.
   Results are returned as { ok, value, decimal, error }.
   `decimal` is a human-friendly string (9 sig figs, strips trailing zeros).
*/

/** Own-property check — prevents inherited prototype names like 'constructor',
 *  'toString', 'hasOwnProperty' from being treated as valid calculator names. */
const _calcHasOwn = (obj, key) => Object.prototype.hasOwnProperty.call(obj, key);

/** Global calculator state. */
const CALC_STATE = {
  // PR-4 (feedback #8): 'home' is the landing mode. togCalc force-
  // resets this on every open, so the value here only matters for
  // the brief window between module load and first togCalc call;
  // keeping it on 'home' means a stray pre-open calcRenderUI (tests,
  // a future HUD widget) renders the mode selector rather than a
  // blank Calculate with no persisted history.
  mode:      'home',             // active mode key
  history:   [],                 // [{input, value, decimal}]
  current:   '',                 // live input expression (flattened string)
  shift:     false,              // SHIFT modifier latch
  alpha:     false,              // ALPHA modifier latch
  angle:     'deg',              // 'deg' | 'rad'
  fractions: true,               // MathI/MathO output (true) vs MathI/DecimalO (false)
  // Legacy session field; output representation belongs to each history entry.
  formatMode: 'decimal',         // Legacy snapshot compatibility; rendering uses entry.format.
  fullscreen: false,             // recording-mode flag
  // Retained for old snapshots; only the BASIC layout is currently exposed.
  calcView:  'basic',            // 'basic' | 'adv'
  // One active overlay panel at a time.
  activePanel: null,             // null | 'history' | 'setup' | 'catalog' | 'help' | 'vars'
  vars:      { A:0,B:0,C:0,D:0,E:0,F:0,x:0,y:0,z:0,M:0, Ans:0 }
};

/* Whitelist of valid CALC_STATE.activePanel values. Module-level
 * const (the codebase uses plain script-globals; calc-core.js
 * loads before persistence.js + calc-ui-v2.js in scripts/bundle.js
 * so consumers see this without an import). frozen so a stray
 * runtime mutation can't broaden the accepted set. */
const CALC_PANEL_VALUES = Object.freeze([
  null, 'history', 'setup', 'catalog', 'help', 'vars'
]);

/* ── TOKENIZER ───────────────────────────────────────────────── */

/** Tokenizes an expression string into {type, value} tokens. */
function _calcTokenize(src){
  const tokens = [];
  let i = 0;
  while(i < src.length){
    const c = src[i];
    if(c === ' '){ i++; continue; }

    // Numbers (incl. decimal, scientific notation e/E). Strict match —
    // rejects malformed literals like "1..2" or "2e+" with an error
    // instead of silently parsing them as `1` or `2`.
    if(/[0-9.]/.test(c)){
      const m = src.slice(i).match(/^(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/);
      if(!m) throw new Error('Bad number literal near: ' + src.slice(i, i+4));
      const degVal = Number(m[0]);
      tokens.push({type:'num', value: degVal});
      i += m[0].length;

      // DMS literal aggregation (feat/calc-dms-input). If the
      // number is immediately followed by ° (U+00B0), optionally
      // consume minute and second components and replace the
      // previously-emitted num token with the decimal-degrees
      // value: deg + min/60 + sec/3600. ASCII ' / " are accepted
      // alongside Unicode ′ (U+2032) / ″ (U+2033) for
      // physical-keyboard friendliness; the DMS button itself
      // inserts the Unicode glyphs so the display reads correctly.
      // Negative DMS works via standard unary minus
      // (`-64°38'` parses as `-(64 + 38/60)`).
      if(src[i] === '°'){
        i++;  // consume °
        let minVal = 0;
        let secVal = 0;
        // Skip whitespace between ° and the next number.
        while(src[i] === ' ') i++;
        // Speculative read for minute component. If the marker
        // doesn't follow, we leave i unchanged so the trailing
        // chars get tokenized normally — no rollback machinery
        // needed because we only advance i AFTER both number +
        // marker are confirmed.
        const minMatch = src.slice(i).match(/^(?:\d+\.?\d*|\.\d+)/);
        if(minMatch){
          let j = i + minMatch[0].length;
          while(src[j] === ' ') j++;
          if(src[j] === '′' || src[j] === "'"){
            minVal = Number(minMatch[0]);
            i = j + 1;  // commit: past number + whitespace + marker
            // Optional second component, same pattern.
            while(src[i] === ' ') i++;
            const secMatch = src.slice(i).match(/^(?:\d+\.?\d*|\.\d+)/);
            if(secMatch){
              let k = i + secMatch[0].length;
              while(src[k] === ' ') k++;
              if(src[k] === '″' || src[k] === '"'){
                secVal = Number(secMatch[0]);
                i = k + 1;
              }
            }
          }
        }
        const decimal = degVal + minVal / 60 + secVal / 3600;
        tokens[tokens.length - 1].value = decimal;
      }
      continue;
    }

    // Identifiers. We have to be careful: button inputs can emit things like
    // `x` followed by `sin(`, which naively concatenates to `xsin(`. Only
    // accept a multi-character identifier when it's a known function, a
    // known constant, or is followed by `(` (meaning it must be a fn call).
    // Otherwise emit a single-character identifier so implicit multiplication
    // can split `xsin(30)` into `x*sin(30)`.
    if(/[a-zA-Z_]/.test(c)){
      let j = i;
      while(j < src.length && /[a-zA-Z0-9_]/.test(src[j])) j++;
      const full = src.slice(i, j);
      // Single-letter names always take the short form — they're the common
      // variable namespace (A-F, x, y, z, M) and should never swallow a
      // following function name.
      if(full.length === 1){
        tokens.push({type:'ident', value: full});
        i = j; continue;
      }
      // Multi-char: accept only if it's a function, constant, multi-letter var,
      // OR followed by '(' AND doesn't start with a multi-letter var prefix.
      // Prevents 'Anssin(30)' from being accepted as 'Anssin' — we split to
      // 'Ans' + 'sin(30)' instead.
      const isFn    = Object.prototype.hasOwnProperty.call(_CALC_FUNCTIONS, full);
      const isConst = Object.prototype.hasOwnProperty.call(_CALC_CONSTANTS, full);
      const nextIsParen = src[j] === '(';
      const MULTI_VARS = ['Ans', 'Inf'];
      const isMultiLetterVar = MULTI_VARS.includes(full);
      const startsWithMultiVar = MULTI_VARS.find(v => full.startsWith(v) && v.length < full.length);
      if(isFn || isConst || isMultiLetterVar){
        tokens.push({type:'ident', value: full});
        i = j; continue;
      }
      if(startsWithMultiVar){
        // Emit the multi-letter var, then continue scanning the rest
        tokens.push({type:'ident', value: startsWithMultiVar});
        i += startsWithMultiVar.length; continue;
      }
      // Check for any known constant/function prefix — e.g. 'pi2' → 'pi' + '2',
      // 'sinx' (when followed by anything non-paren) should keep 'sin' as a
      // name the RPN builder can complain about. Longest match wins.
      let knownPrefix = '';
      for(const name of Object.keys(_CALC_CONSTANTS)){
        if(full.startsWith(name) && name.length > knownPrefix.length && name.length < full.length){
          knownPrefix = name;
        }
      }
      for(const name of Object.keys(_CALC_FUNCTIONS)){
        if(full.startsWith(name) && name.length > knownPrefix.length && name.length < full.length){
          knownPrefix = name;
        }
      }
      if(knownPrefix){
        tokens.push({type:'ident', value: knownPrefix});
        i += knownPrefix.length; continue;
      }
      if(nextIsParen){
        // Unknown multi-char name followed by '(' — accept as-is so the RPN
        // builder can report 'Unknown function' rather than silently split.
        tokens.push({type:'ident', value: full});
        i = j; continue;
      }
      // Break apart — emit each char as its own identifier
      tokens.push({type:'ident', value: src[i]});
      i += 1; continue;
    }

    // Operators + grouping
    if('+-*/^%(),!'.indexOf(c) >= 0){
      tokens.push({type:'op', value: c});
      i++; continue;
    }

    // Unicode fallbacks (templates may emit these)
    if(c === '×'){ tokens.push({type:'op', value:'*'}); i++; continue; }
    if(c === '÷'){ tokens.push({type:'op', value:'/'}); i++; continue; }
    if(c === '−'){ tokens.push({type:'op', value:'-'}); i++; continue; }
    if(c === 'π'){ tokens.push({type:'ident', value:'pi'}); i++; continue; }

    throw new Error('Unexpected character: ' + c);
  }
  return tokens;
}

/* ── PARSER (shunting-yard → RPN) ────────────────────────────── */

const _CALC_PRECEDENCE = { '+':1, '-':1, '*':2, '/':2, '%':2, 'u-':3, '^':4, '!':5 };
const _CALC_RIGHT_ASSOC = { '^':true, 'u-':true };

function _calcToRPN(tokens, legacyPercent = false){
  const out = [];
  const stack = [];
  let prev = null; // track previous token to detect unary minus and implicit *

  for(let i = 0; i < tokens.length; i++){
    const t = tokens[i];

    // Implicit multiplication rules:
    //   num num        → num * num
    //   num ident      → num * ident (e.g., 2x)
    //   num (          → num * (
    //   ) (            → ) * (
    //   ) num / ident  → ) * ...
    //   ident (        → ONLY when ident is a variable (not a function). For
    //                    functions, the '(' starts the function call.
    const prevIsFn = prev && prev.type === 'ident' && _calcHasOwn(_CALC_FUNCTIONS, prev.value);
    if(prev && (
        (t.type === 'num'   && (prev.type === 'num' || prev.type === 'ident' || (prev.type === 'op' && (prev.value === ')' || prev.value === '!')))) ||
        (t.type === 'ident' && (prev.type === 'num' || (prev.type === 'op' && (prev.value === ')' || prev.value === '!')))) ||
        (t.type === 'op' && t.value === '(' && (
          prev.type === 'num' ||
          (prev.type === 'ident' && !prevIsFn) ||
          (prev.type === 'op' && (prev.value === ')' || prev.value === '!'))
        ))
    )){
      // synthesize a *
      while(stack.length){
        const top = stack[stack.length-1];
        if(top.type === 'op' && top.value !== '(' &&
           (_CALC_PRECEDENCE[top.value] > _CALC_PRECEDENCE['*'] ||
            (_CALC_PRECEDENCE[top.value] === _CALC_PRECEDENCE['*'] && !_CALC_RIGHT_ASSOC['*']))){
          out.push(stack.pop());
        } else break;
      }
      stack.push({type:'op', value:'*'});
    }

    if(t.type === 'num'){ out.push(t); prev = t; continue; }

    if(t.type === 'ident'){
      // Look ahead: if next is '(' and this identifier is a known function,
      // push as fn-or-var for the ')' handler to pop into a fn call. Otherwise
      // emit as a variable immediately — no stacking, no implicit '*'.
      const next = tokens[i + 1];
      const isFnCall = next && next.type === 'op' && next.value === '(' && _calcHasOwn(_CALC_FUNCTIONS, t.value);
      if(isFnCall){
        stack.push({type:'fn-or-var', value: t.value});
      } else {
        out.push({type:'var', value: t.value});
      }
      prev = t; continue;
    }

    if(t.type === 'op'){
      const op = t.value;

      if(op === '('){ stack.push({type:'op', value:'('}); prev = t; continue; }

      if(op === ')'){
        while(stack.length && !(stack[stack.length-1].type === 'op' && stack[stack.length-1].value === '(')){
          out.push(stack.pop());
        }
        if(!stack.length) throw new Error('Mismatched parentheses');
        stack.pop(); // remove '('
        // If top is a fn-or-var — it becomes a function call
        if(stack.length && stack[stack.length-1].type === 'fn-or-var'){
          out.push({type:'fn', value: stack.pop().value});
        }
        prev = t; continue;
      }

      if(op === ','){
        while(stack.length && !(stack[stack.length-1].type === 'op' && stack[stack.length-1].value === '(')){
          out.push(stack.pop());
        }
        prev = t; continue;
      }

      // Percentage is postfix in new input; legacy replay alone uses binary %.
      if(op === '%' && !legacyPercent){
        if(!prev || (prev.type === 'op' && ![')', '!', '%'].includes(prev.value))){
          throw new Error('Percentage needs a preceding value');
        }
        out.push({type:'op', value:'percent'}); prev = {type:'op', value:'!'}; continue;
      }

      // Unary minus detection
      let tok = t;
      if(op === '-' && (prev === null || (prev.type === 'op' && prev.value !== ')' && prev.value !== '!'))){
        tok = {type:'op', value:'u-'};
      }

      // Factorial (postfix) — immediate push to output
      if(op === '!'){ out.push({type:'op', value:'!'}); prev = t; continue; }

      // Prefix unary minus — push directly without draining higher-precedence
      // binary ops. Otherwise `2^-2` would drain `^` before pushing `u-`,
      // producing malformed RPN.
      if(tok.value === 'u-'){
        stack.push(tok);
        prev = t; continue;
      }

      while(stack.length){
        const top = stack[stack.length-1];
        if(top.type === 'op' && top.value !== '('){
          const tp = _CALC_PRECEDENCE[top.value] || 0;
          const cp = _CALC_PRECEDENCE[tok.value] || 0;
          if(tp > cp || (tp === cp && !_CALC_RIGHT_ASSOC[tok.value])){
            out.push(stack.pop());
          } else break;
        } else break;
      }
      stack.push(tok);
      prev = t; continue;
    }
  }

  while(stack.length){
    const top = stack.pop();
    if(top.type === 'op' && (top.value === '(' || top.value === ')')) throw new Error('Mismatched parentheses');
    // Lone fn-or-var at end becomes a variable reference
    if(top.type === 'fn-or-var') out.push({type:'var', value: top.value});
    else out.push(top);
  }
  return out;
}

/* ── EVALUATOR ───────────────────────────────────────────────── */

const _CALC_CONSTANTS = { pi: Math.PI, e: Math.E, Inf: Infinity };

function _calcAngleIn(x){ return CALC_STATE.angle === 'deg' ? x * Math.PI / 180 : x; }
function _calcAngleOut(x){ return CALC_STATE.angle === 'deg' ? x * 180 / Math.PI : x; }

function _calcFactorial(n){
  if(!Number.isInteger(n) || n < 0) return NaN;
  if(n > 170) return Infinity;
  let r = 1;
  for(let i = 2; i <= n; i++) r *= i;
  return r;
}

/* nPr / nCr — multiplicative, not factorial-quotient.
 *
 * The previous forms were fact(n)/fact(n-r) and fact(n)/(fact(r)·fact(n-r)).
 * Because _calcFactorial saturates to Infinity above 170, ANY n > 170 gave
 * Infinity/Infinity = NaN even when the true answer is small and perfectly
 * representable — 200 nCr 2 is 19900, and it returned NaN. That NaN then landed
 * in HISTORY as a result with no error shown.
 *
 * Building the product term by term keeps every intermediate near the size of
 * the answer, so the domain is limited by the ANSWER overflowing rather than by
 * an intermediate. Cost is O(r) with r clamped to min(r, n-r) for nCr, so the
 * worst case is ~n/2 multiplications; n is itself bounded below, giving a hard
 * ceiling on the work. Out-of-domain inputs return NaN, which _calcEvalRPN
 * surfaces as an error rather than a silent result. */
const CALC_COMB_MAX_N = 1e7;   // ~5e6 multiplications worst case; ms, not minutes

function _calcNPr(n, r){
  if(!Number.isInteger(n) || !Number.isInteger(r)) return NaN;
  if(n < 0 || r < 0 || r > n) return NaN;          // r > n is undefined, not 0
  if(n > CALC_COMB_MAX_N) return NaN;              // refuse rather than grind
  let out = 1;
  for(let i = 0; i < r; i++){
    out *= (n - i);
    if(!Number.isFinite(out)) return Infinity;     // genuine overflow, bail early
  }
  return out;
}

function _calcNCr(n, r){
  if(!Number.isInteger(n) || !Number.isInteger(r)) return NaN;
  if(n < 0 || r < 0 || r > n) return NaN;
  if(n > CALC_COMB_MAX_N) return NaN;
  // C(n,r) === C(n,n-r); taking the smaller r halves the loop and keeps the
  // running value smaller.
  const k = Math.min(r, n - r);
  let out = 1;
  for(let i = 1; i <= k; i++){
    // Multiply then divide each step: (out * (n-k+i)) / i is exact for all
    // intermediates that fit, because the running value is always a binomial
    // coefficient times an integer.
    out = out * (n - k + i) / i;
    if(!Number.isFinite(out)) return Infinity;
  }
  // Floating division can leave a hair of error on large inputs; the true
  // value is an integer, so snap when we are within representable range.
  return out <= Number.MAX_SAFE_INTEGER ? Math.round(out) : out;
}

/** Real integer-index roots, including reciprocal roots for negative indices. */
function _calcNthRoot(rad, index){
  if(!Number.isSafeInteger(index) || index === 0 || Number.isNaN(rad)) return NaN;
  if(rad < 0 && index % 2 === 0) return NaN;
  return rad < 0 ? -Math.pow(-rad, 1/index) : Math.pow(rad, 1/index);
}

const _CALC_FUNCTIONS = {
  sin:  a => Math.sin(_calcAngleIn(a)),
  cos:  a => Math.cos(_calcAngleIn(a)),
  tan:  a => Math.tan(_calcAngleIn(a)),
  asin: a => _calcAngleOut(Math.asin(a)),
  acos: a => _calcAngleOut(Math.acos(a)),
  atan: a => _calcAngleOut(Math.atan(a)),
  sinh: Math.sinh, cosh: Math.cosh, tanh: Math.tanh,
  log:  a => Math.log10(a),
  log10:a => Math.log10(a),
  ln:   a => Math.log(a),
  exp:  Math.exp,
  sqrt: Math.sqrt,
  cbrt: Math.cbrt,
  nthroot: _calcNthRoot,
  mixed: (w,n,d) => (w < 0 || Object.is(w, -0)) ? -(Math.abs(w) + n/d) : w + n/d,
  mod: (a,b) => a % b,
  abs:  Math.abs,
  round: Math.round,
  floor: Math.floor,
  ceil:  Math.ceil,
  min:   Math.min,
  max:   Math.max,
  pow:   (a,b) => Math.pow(a,b),
  fact:  _calcFactorial,
  nCr:   _calcNCr,
  nPr:   _calcNPr,
  gcd:   (a,b) => { a=Math.abs(Math.round(a)); b=Math.abs(Math.round(b)); while(b){ [a,b]=[b,a%b]; } return a; },
  lcm:   (a,b) => { const g = _CALC_FUNCTIONS.gcd(a,b); return g ? Math.abs(a*b)/g : 0; }
};

/** Shared arities for evaluation and legacy replay serialization. */
function _calcFunctionArity(fn){
  if(fn === 'mixed') return 3;
  return ['pow','nCr','nPr','gcd','lcm','min','max','nthroot','mod'].includes(fn) ? 2 : 1;
}

/** Only pre-version-2 saved expressions use binary %. Convert their RPN to
 * explicit mod calls at recall, without mutating stored display/result data.
 * Non-% entries and new postfix expressions are returned byte-for-byte. */
function calcHistoryExpression(entry, expr){
  if(entry.syntaxVersion === 2 || !expr.includes('%')) return expr;
  const stack = [];
  for(const t of _calcToRPN(_calcTokenize(expr), true)){
    if(t.type === 'num' || t.type === 'var') stack.push(String(t.value));
    else if(t.type === 'fn'){
      const arity = _calcFunctionArity(t.value);
      if(stack.length < arity) throw new Error('Invalid legacy replay');
      stack.push(t.value + '(' + stack.splice(-arity).join(',') + ')');
    } else if(t.type === 'op'){
      if(t.value === 'u-' || t.value === '!'){
        if(!stack.length) throw new Error('Invalid legacy replay');
        const a = stack.pop();
        stack.push(t.value === 'u-' ? '-(' + a + ')' : '(' + a + ')!');
      } else {
        if(stack.length < 2) throw new Error('Invalid legacy replay');
        const b = stack.pop(), a = stack.pop();
        stack.push(t.value === '%' ? 'mod(' + a + ',' + b + ')' : '(' + a + t.value + b + ')');
      }
    }
  }
  if(stack.length !== 1) throw new Error('Invalid legacy replay');
  return stack[0];
}

/** Persisted output aliases normalize without touching unrelated entry fields. */
function calcNormalizeHistory(history){
  return history.map(entry => entry && entry.format === 'improper' ? {...entry, format:'fraction'} : entry);
}

/** Evaluates an RPN token stream. Throws on error. */
function _calcEvalRPN(rpn){
  const stk = [];
  // Function arity — for functions we know; anything else assumed 1

  for(const t of rpn){
    if(t.type === 'num'){ stk.push(t.value); continue; }

    if(t.type === 'var'){
      const n = t.value;
      if(_calcHasOwn(_CALC_CONSTANTS, n)){ stk.push(_CALC_CONSTANTS[n]); continue; }
      if(_calcHasOwn(CALC_STATE.vars, n)){ stk.push(CALC_STATE.vars[n]); continue; }
      throw new Error('Unknown name: ' + n);
    }

    if(t.type === 'fn'){
      const fn = _CALC_FUNCTIONS[t.value];
      if(!fn){
        // Maybe it's a constant/variable used without ()
        if(_calcHasOwn(_CALC_CONSTANTS, t.value)){ stk.push(_CALC_CONSTANTS[t.value]); continue; }
        if(_calcHasOwn(CALC_STATE.vars, t.value)){ stk.push(CALC_STATE.vars[t.value]); continue; }
        throw new Error('Unknown function: ' + t.value);
      }
      const n = _calcFunctionArity(t.value);
      if(stk.length < n) throw new Error('Bad arguments to ' + t.value);
      const args = stk.splice(stk.length - n, n);
      stk.push(fn.apply(null, args));
      continue;
    }

    if(t.type === 'op'){
      const op = t.value;
      if(op === 'percent'){
        if(!stk.length) throw new Error('Bad percentage');
        stk.push(stk.pop()/100); continue;
      }
      if(op === 'u-'){
        if(!stk.length) throw new Error('Bad unary minus');
        stk.push(-stk.pop()); continue;
      }
      if(op === '!'){
        if(!stk.length) throw new Error('Bad factorial');
        stk.push(_calcFactorial(stk.pop())); continue;
      }
      if(stk.length < 2) throw new Error('Bad operator: ' + op);
      const b = stk.pop(), a = stk.pop();
      switch(op){
        case '+': stk.push(a + b); break;
        case '-': stk.push(a - b); break;
        case '*': stk.push(a * b); break;
        case '/': stk.push(a / b); break;
        case '%': stk.push(a % b); break;
        case '^': stk.push(Math.pow(a, b)); break;
        default:  throw new Error('Bad op: ' + op);
      }
    }
  }
  if(stk.length !== 1) throw new Error('Malformed expression');
  return stk[0];
}

/* ── CALCULUS PLACEHOLDERS (Σ, ∫, d/dx, Π) ────────────────────
   Templates for summation, integration, derivative, and product cannot
   be serialized to a plain expression string because their body depends
   on a bound variable. Instead, their `serialize()` registers the slot
   strings in this map and returns an opaque token `__HGL_PH_N__`. On
   evaluate, we resolve each token by binding the loop variable, re-
   calling calcEvaluate on the body, and substituting the numeric result
   into the outer expression. Tokens are single-use — cleared after each
   top-level evaluation so stale bodies don't leak between calls. */
const _CALC_PLACEHOLDERS = {};
let _calcPlaceholderCounter = 0;
const _CALC_PH_RE = /__HGL_PH_\d+__/;

function _calcRegisterPlaceholder(kind, slots){
  const id = '__HGL_PH_' + (++_calcPlaceholderCounter) + '__';
  _CALC_PLACEHOLDERS[id] = { kind, slots };
  return id;
}

/** Adaptive Simpson's rule integrator. Recursively subdivides until the
 *  two half-interval Simpson estimates agree within tol, or maxDepth is
 *  reached. Returns the integral of f from a to b. */
function _calcSimpson(f, a, b){
  const c = (a + b) / 2;
  return (b - a) / 6 * (f(a) + 4 * f(c) + f(b));
}
function _calcAdaptiveSimpson(f, a, b, tol, whole, depth){
  const c  = (a + b) / 2;
  const left  = _calcSimpson(f, a, c);
  const right = _calcSimpson(f, c, b);
  const diff  = left + right - whole;
  if(depth <= 0 || Math.abs(diff) < 15 * tol){
    return left + right + diff / 15;
  }
  return _calcAdaptiveSimpson(f, a, c, tol/2, left,  depth - 1) +
         _calcAdaptiveSimpson(f, c, b, tol/2, right, depth - 1);
}
function _calcIntegrate(f, a, b){
  if(a === b) return 0;
  const sign = b < a ? -1 : 1;
  if(b < a){ const t = a; a = b; b = t; }
  const whole = _calcSimpson(f, a, b);
  return sign * _calcAdaptiveSimpson(f, a, b, 1e-8, whole, 18);
}

/** Numerical derivative via central difference + Richardson extrapolation.
 *  D ≈ (4·D(h/2) − D(h)) / 3, which cancels the O(h²) error term so the
 *  result is O(h⁴) accurate. h scales with |x| so it works for large and
 *  small arguments without losing precision. */
function _calcDerivative(f, x){
  const h = Math.max(1e-6, Math.abs(x) * 1e-6);
  const d1 = (f(x + h)     - f(x - h))     / (2 * h);
  const d2 = (f(x + h / 2) - f(x - h / 2)) / h;
  return (4 * d2 - d1) / 3;
}

/** Evaluates a single placeholder node — binds the loop variable (saving
 *  its prior value), evaluates slots, restores the variable, and returns
 *  the numeric result. Throws on nested evaluation errors. */
function _calcEvalPlaceholder(node){
  const { kind, slots } = node;
  const evalStr = (s, fallback) => {
    const str = String(s == null ? '' : s).trim();
    if(!str) return fallback;
    const r = calcEvaluate(str);
    if(!r.ok) throw new Error(r.error || 'Bad sub-expression');
    if(r.value == null || !Number.isFinite(r.value)) throw new Error('Non-finite limit');
    return r.value;
  };

  if(kind === 'sum' || kind === 'prod'){
    const name = String(slots.var || '').trim() || 'x';
    if(!_calcHasOwn(CALC_STATE.vars, name)) throw new Error('Unknown variable: ' + name);
    const lo = Math.round(evalStr(slots.lo, 0));
    const hi = Math.round(evalStr(slots.hi, 0));
    if(!Number.isFinite(lo) || !Number.isFinite(hi)) throw new Error('Bad bounds');
    if(hi - lo > 1e6) throw new Error('Range too large');
    const body = String(slots.body || '').trim();
    if(!body) throw new Error('Empty body');
    const saved = CALC_STATE.vars[name];
    let acc = kind === 'sum' ? 0 : 1;
    try {
      for(let i = lo; i <= hi; i++){
        CALC_STATE.vars[name] = i;
        const r = calcEvaluate(body);
        if(!r.ok) throw new Error(r.error || 'Bad body');
        if(kind === 'sum') acc += r.value;
        else               acc *= r.value;
      }
    } finally {
      CALC_STATE.vars[name] = saved;
    }
    return acc;
  }

  if(kind === 'integ'){
    const name = String(slots.var || '').trim() || 'x';
    if(!_calcHasOwn(CALC_STATE.vars, name)) throw new Error('Unknown variable: ' + name);
    const lo = evalStr(slots.lo, 0);
    const hi = evalStr(slots.hi, 0);
    const body = String(slots.body || '').trim();
    if(!body) throw new Error('Empty body');
    const saved = CALC_STATE.vars[name];
    try {
      const f = x => {
        CALC_STATE.vars[name] = x;
        const r = calcEvaluate(body);
        if(!r.ok) throw new Error(r.error || 'Bad body');
        return r.value;
      };
      return _calcIntegrate(f, lo, hi);
    } finally {
      CALC_STATE.vars[name] = saved;
    }
  }

  if(kind === 'deriv'){
    const name = String(slots.var || '').trim() || 'x';
    if(!_calcHasOwn(CALC_STATE.vars, name)) throw new Error('Unknown variable: ' + name);
    const at   = evalStr(slots.at, 0);
    const body = String(slots.body || '').trim();
    if(!body) throw new Error('Empty body');
    const saved = CALC_STATE.vars[name];
    try {
      const f = x => {
        CALC_STATE.vars[name] = x;
        const r = calcEvaluate(body);
        if(!r.ok) throw new Error(r.error || 'Bad body');
        return r.value;
      };
      return _calcDerivative(f, at);
    } finally {
      CALC_STATE.vars[name] = saved;
    }
  }

  throw new Error('Unknown placeholder: ' + kind);
}

/** Resolves every `__HGL_PH_N__` in `src` to a numeric literal by
 *  evaluating the registered placeholder. Repeats until no tokens remain.
 *  Placeholder entries are consumed (deleted) as they're resolved so the
 *  map doesn't grow unbounded across sessions. */
function _calcResolvePlaceholders(src){
  let expr = String(src);
  let guard = 0;
  while(_CALC_PH_RE.test(expr)){
    if(guard++ > 200) throw new Error('Placeholder recursion limit');
    const m = expr.match(_CALC_PH_RE);
    const id = m[0];
    const ph = _CALC_PLACEHOLDERS[id];
    if(!ph) throw new Error('Stale placeholder');
    const val = _calcEvalPlaceholder(ph);
    delete _CALC_PLACEHOLDERS[id];
    // Wrap result so unary-minus / operator context stays correct
    const literal = Number.isFinite(val) ? '(' + val + ')' : (val > 0 ? '(1/0)' : '(-1/0)');
    expr = expr.split(id).join(literal);
  }
  return expr;
}

/**
 * Evaluates an expression string. Returns { ok, value, decimal, error }.
 * @param {string} src - expression to evaluate
 */
function calcEvaluate(src){
  if(!src || !String(src).trim()) return { ok:true, value:null, decimal:'', error:null };
  try {
    const resolved = _calcResolvePlaceholders(String(src));
    const tokens = _calcTokenize(resolved);
    const rpn    = _calcToRPN(tokens);
    const value  = _calcEvalRPN(rpn);
    if(!Number.isFinite(value) && !Number.isNaN(value)){
      return { ok:true, value, decimal: (value > 0 ? '∞' : '-∞'), error:null };
    }
    if(Number.isNaN(value)) return { ok:false, value:NaN, decimal:'Err', error:'Math error' };
    /* feat/calc-format-dms-render: drop eager fraction
     * computation. The decimal field is now always plain
     * decimal — _calcFormatDisplay reads entry.value lazily on
     * render and applies CALC_STATE.formatMode (sticky) /
     * entry.dmsActive (per-result) there. The decimal field is
     * retained for replay metadata, history-row text fallback,
     * and back-compat with persisted entries that pre-date
     * entry.value. */
    const decimal = calcFormatResult(value);
    return { ok:true, value, decimal, error:null };
  } catch(e){
    return { ok:false, value:null, decimal:'Err', error: e.message };
  }
}

/**
 * Formats a numeric result for display — trims trailing zeros, uses sci
 * notation past 10 digits, and truncates to 10 significant figures.
 * @param {number} n
 */
function calcFormatResult(n){
  if(n === 0) return '0';
  const abs = Math.abs(n);
  if(abs >= 1e10 || abs < 1e-6){
    return n.toExponential(6).replace(/0+e/,'e').replace(/\.e/,'e');
  }
  let s = Number(n.toPrecision(10)).toString();
  // Strip trailing zeros after decimal
  if(s.indexOf('.') >= 0) s = s.replace(/0+$/,'').replace(/\.$/,'');
  return s;
}

/**
 * feat/calc-format-dms-render: lazy formatters for the displayed
 * answer. Render sites call _calcFormatDisplay(entry) on every
 * paint — it reads CALC_STATE.formatMode (sticky) and
 * entry.dmsActive (per-result) and reformats entry.value lazily.
 *
 * Fall-through ladder:
 *   entry.dmsActive  → _calcFormatDMS  (per-result wins)
 *   entry.value      → _calcFormatNumber per CALC_STATE.formatMode
 *   else             → entry.decimal (older snapshots without value)
 *
 * Irrational results (calcTryFraction returns null) fall through
 * to plain decimal regardless of the requested entry format — fraction modes
 * silently degrade.
 */
function _calcFormatNumber(value, mode){
  if(!Number.isFinite(value)) return calcFormatResult(value);
  if(mode === 'decimal') return calcFormatResult(value);
  const frac = calcTryFraction(value);
  if(!frac) return calcFormatResult(value);   // irrational → decimal
  const { n, d } = frac;
  if(mode === 'fraction' || mode === 'improper'){
    // improper is accepted only as a legacy output alias.
    return `${n}/${d}`;
  }
  if(mode === 'mixed'){
    const sign = n < 0 ? -1 : 1;
    const absN = Math.abs(n);
    const whole = Math.trunc(absN / d);
    const rem = absN - whole * d;
    if(rem === 0){
      // CR feedback: use Unicode minus consistently across all
      // negative-result branches in this formatter.
      return sign < 0 ? `−${whole}` : String(whole);
    }
    if(whole === 0){
      // No whole part — render as plain fraction. Unicode minus
      // on the numerator matches the wholeStr branch below.
      const numStr = sign < 0 ? `−${absN}` : String(absN);
      return `${numStr}/${d}`;
    }
    // Standard mixed form. Unicode minus matches existing trace
    // formatter convention (graphPanel _gpFmtTrace, calc-ui-v2).
    const wholeStr = sign < 0 ? `−${whole}` : `${whole}`;
    return `${wholeStr} ${rem}/${d}`;
  }
  return calcFormatResult(value);
}

/** Decimal-degrees → degrees-minutes-seconds string. When called
 *  on a value originated in radian-mode trig, the angleMode=='rad'
 *  path converts via × 180/π first — DMS is purely degree
 *  notation. */
function _calcFormatDMS(value, angleMode){
  if(!Number.isFinite(value)) return calcFormatResult(value);
  let degrees = (angleMode === 'rad') ? value * 180 / Math.PI : value;
  const sign = degrees < 0 ? -1 : 1;
  const absDeg = Math.abs(degrees);
  let d = Math.trunc(absDeg);
  const mFrac = (absDeg - d) * 60;
  let m = Math.trunc(mFrac);
  let s = (mFrac - m) * 60;
  // Round seconds to 3 decimals; carry to minutes if rounding
  // produces 60. Carry minutes to degrees on the same condition.
  s = Math.round(s * 1000) / 1000;
  if(s >= 60){ s -= 60; m += 1; }
  if(m >= 60){ m -= 60; d += 1; }
  // Strip trailing-zero seconds for cleaner display when integral
  const sStr = String(s);
  const signStr = sign < 0 ? '−' : '';
  return `${signStr}${d}° ${m}′ ${sStr}″`;
}

/** Canonical display formatter — call this from every render
 *  site that previously read entry.decimal. */
function _calcFormatDisplay(entry){
  if(!entry) return '';
  // Per-result DMS takes precedence over the entry's number representation.
  // CR feedback: the field is CALC_STATE.angle (not angleMode);
  // and even with the right field name, reading the LIVE state
  // is wrong — a result computed in deg mode then viewed after
  // the user switched to rad mode would convert as if the
  // numeric value were radians. Use entry.angle (snapshotted at
  // push time in _calcExecute) and fall back to live state for
  // pre-this-PR snapshots that lack the field.
  if(entry.dmsActive && Number.isFinite(entry.value)){
    const evalAngle = (typeof entry.angle === 'string') ? entry.angle : CALC_STATE.angle;
    return _calcFormatDMS(entry.value, evalAngle);
  }
  if(Number.isFinite(entry.value)){
    // Per-entry format (fix/calc-ac-clean-slate-and-format-per-
    // result). Earlier sticky CALC_STATE.formatMode replaced by
    // entry.format so cycling FORMAT only affects the displayed
    // last entry, not every row and not future calcs. Absent
    // field → decimal. Old persisted entries without .format
    // render as decimal via the same fallback.
    return _calcFormatNumber(entry.value, entry.format || 'decimal');
  }
  // Older entry without value (pre-this-PR snapshot) — fall back to
  // the frozen decimal string.
  return (typeof entry.decimal === 'string') ? entry.decimal : '';
}

/**
 * Tries to render a result as an exact fraction when the value is rational
 * with small denominator (fx-8200 MathO behavior). Returns null otherwise.
 * @param {number} n
 */
function calcTryFraction(n){
  if(!Number.isFinite(n) || Number.isInteger(n)) return null;
  const sign = n < 0 ? -1 : 1;
  const v = Math.abs(n);
  // Continued-fraction style search — cap denominator at 10000
  let h1 = 1, h0 = 0, k1 = 0, k0 = 1;
  let b = v;
  for(let i = 0; i < 40; i++){
    const a = Math.floor(b);
    const h2 = a * h1 + h0;
    const k2 = a * k1 + k0;
    if(k2 > 10000) break;
    if(Math.abs(v - h2 / k2) < 1e-12){
      return { n: sign * h2, d: k2 };
    }
    h0 = h1; h1 = h2;
    k0 = k1; k1 = k2;
    if(b - a === 0) break;
    b = 1 / (b - a);
  }
  return null;
}

