/* ==== src/js/features/calc/calc-templates.js ==== */
/* features/calc/calc-templates.js — Natural-display template engine

   Templates are structured expression nodes with named slots. The user types
   into a slot, Tab/→ moves to the next slot. Templates render as MathML-ish
   HTML and serialize to a plain math expression for the evaluator.

   Node shape: { kind, slots: { slotName: Node[] } }
   Text atoms are just strings.

   Example: pressing [▢/▢] after typing "1+" yields:
     ['1','+', {kind:'frac', slots:{num:[''], den:['']}}]
   Cursor lands in `num`. User types "2", arrow-down moves to `den`, types "3",
   arrow-right exits the template.

   Serialization of frac: "(num)/(den)" — parens are added for safety so the
   evaluator's precedence rules still work.
*/

/** Catalog of template definitions. */
const CALC_TEMPLATES = {
  frac:   { slots:['num','den'],       render:(s) => `<span class="ct-frac"><span class="ct-num" data-slot="num">${s.num}</span><span class="ct-bar"></span><span class="ct-den" data-slot="den">${s.den}</span></span>`,
            serialize:(s) => `(${s.num||0})/(${s.den||1})` },
  mixed:  { slots:['w','num','den'],   render:(s) => `<span class="ct-mixed"><span class="ct-w" data-slot="w">${s.w}</span><span class="ct-frac"><span class="ct-num" data-slot="num">${s.num}</span><span class="ct-bar"></span><span class="ct-den" data-slot="den">${s.den}</span></span></span>`,
            serialize:(s) => `mixed(${s.w||0},${s.num||0},${s.den||1})`,
            display:(s) => `${s.w||0} ${s.num||0}⁄${s.den||1}` },
  pow:    { slots:['base','exp'],      render:(s) => `<span class="ct-pow"><span class="ct-base" data-slot="base">${s.base}</span><sup class="ct-exp" data-slot="exp">${s.exp}</sup></span>`,
            serialize:(s) => `(${s.base||0})^(${s.exp||1})` },
  sqrt:   { slots:['rad'],             render:(s) => `<span class="ct-sqrt"><span class="ct-radsym">√</span><span class="ct-rad" data-slot="rad">${s.rad}</span></span>`,
            serialize:(s) => `sqrt(${s.rad||0})` },
  nroot:  { slots:['deg','rad'],       render:(s) => `<span class="ct-nroot"><sup class="ct-deg" data-slot="deg">${s.deg}</sup><span class="ct-radsym">√</span><span class="ct-rad" data-slot="rad">${s.rad}</span></span>`,
            serialize:(s) => `nthroot(${s.rad||0},${s.deg||2})` },
  square: { slots:['base'], render:(s) => `<span class="ct-pow"><span data-slot="base">${s.base}</span><sup>2</sup></span>`, serialize:s => `(${s.base||0})^2` },
  cube: { slots:['base'], render:(s) => `<span class="ct-pow"><span data-slot="base">${s.base}</span><sup>3</sup></span>`, serialize:s => `(${s.base||0})^3` },
  cbrt: { slots:['rad'], render:(s) => `<span class="ct-nroot"><sup>3</sup>√<span class="ct-rad" data-slot="rad">${s.rad}</span></span>`, serialize:s => `cbrt(${s.rad||0})` },
  reciprocal: { slots:['x'], render:(s) => `<span class="ct-pow"><span data-slot="x">${s.x}</span><sup>−1</sup></span>`, serialize:s => `(${s.x||0})^(-1)` },
  pow10: { slots:['exp'], render:(s) => `<span class="ct-pow">10<sup data-slot="exp">${s.exp}</sup></span>`, serialize:s => `10^(${s.exp||0})` },
  abs:    { slots:['x'],               render:(s) => `<span class="ct-abs">|<span class="ct-x" data-slot="x">${s.x}</span>|</span>`,
            serialize:(s) => `abs(${s.x||0})` },
  log:    { slots:['base','arg'],      render:(s) => `<span class="ct-log">log<sub class="ct-base" data-slot="base">${s.base}</sub><span class="ct-paren">(</span><span class="ct-arg" data-slot="arg">${s.arg}</span><span class="ct-paren">)</span></span>`,
            serialize:(s) => `(ln(${s.arg||1})/ln(${s.base||10}))` },
  sum:    { slots:['var','lo','hi','body'],
            render:(s) => `<span class="ct-sum"><span class="ct-sumsym">∑</span><span class="ct-sumlimits"><sup data-slot="hi">${s.hi}</sup><sub><span data-slot="var">${s.var}</span>=<span data-slot="lo">${s.lo}</span></sub></span><span class="ct-sumbody" data-slot="body">${s.body}</span></span>`,
            serialize:(s) => _calcRegisterPlaceholder('sum', s),
            display:(s)   => `Σ[${s.var||'i'}=${s.lo||0}..${s.hi||0}](${s.body||0})` },
  prod:   { slots:['var','lo','hi','body'],
            render:(s) => `<span class="ct-sum"><span class="ct-sumsym">∏</span><span class="ct-sumlimits"><sup data-slot="hi">${s.hi}</sup><sub><span data-slot="var">${s.var}</span>=<span data-slot="lo">${s.lo}</span></sub></span><span class="ct-sumbody" data-slot="body">${s.body}</span></span>`,
            serialize:(s) => _calcRegisterPlaceholder('prod', s),
            display:(s)   => `Π[${s.var||'i'}=${s.lo||0}..${s.hi||0}](${s.body||0})` },
  integ:  { slots:['lo','hi','body','var'],
            render:(s) => `<span class="ct-int">∫<span class="ct-intlimits"><sup data-slot="hi">${s.hi}</sup><sub data-slot="lo">${s.lo}</sub></span><span class="ct-intbody" data-slot="body">${s.body}</span>d<span data-slot="var">${s.var}</span></span>`,
            serialize:(s) => _calcRegisterPlaceholder('integ', s),
            display:(s)   => `∫[${s.lo||0}..${s.hi||0}](${s.body||0})d${s.var||'x'}` },
  deriv:  { slots:['var','at','body'],
            render:(s) => `<span class="ct-deriv"><span class="ct-derivsym"><sup>d</sup>⁄<sub>d<span data-slot="var">${s.var}</span></sub></span><span class="ct-paren">(</span><span data-slot="body">${s.body}</span><span class="ct-paren">)</span><span class="ct-at"><sub>|<sub data-slot="at">${s.at}</sub></sub></span></span>`,
            serialize:(s) => _calcRegisterPlaceholder('deriv', s),
            display:(s)   => `d/d${s.var||'x'}(${s.body||0})|${s.var||'x'}=${s.at||0}` }
};

/* ── INPUT MODEL ─────────────────────────────────────────────── */

/**
 * The current input is an array of atoms. Each atom is either a string
 * (character) or a template node {kind, slots:{...Node[]}}.
 * The cursor is tracked as a path — array of indices into nested slots.
 */
const CALC_INPUT = {
  atoms:  [],                        // root atom array
  cursor: { path: [], pos: 0 },      // path = [] means at root; pos = index
};

/** Clears the input to empty. */
function calcInputClear(){
  CALC_INPUT.atoms = [];
  CALC_INPUT.cursor = { path: [], pos: 0 };
}

/** Returns the atom-array at a cursor path. */
function _calcAtomsAt(path){
  let arr = CALC_INPUT.atoms;
  for(const step of path){
    const node = arr[step.idx];
    if(!node || !node.slots) return arr;
    arr = node.slots[step.slot];
    if(!Array.isArray(arr)){
      // Slot stored as string — normalize to char array of atoms
      arr = (arr || '').split('');
      node.slots[step.slot] = arr;
    }
  }
  return arr;
}

/** Inserts a character at the cursor. */
function calcInputInsertChar(ch){
  const arr = _calcAtomsAt(CALC_INPUT.cursor.path);
  arr.splice(CALC_INPUT.cursor.pos, 0, ch);
  CALC_INPUT.cursor.pos++;
}

/** Inserts a string at the cursor (atom-by-atom). */
function calcInputInsertString(s){
  for(const ch of String(s)) calcInputInsertChar(ch);
}

/** Known function names sorted longest-first so multi-char names
 *  match before their substrings (e.g. "asin" before "sin"). Lazy
 *  + cached: _CALC_FUNCTIONS is declared in calc-core.js which the
 *  bundler concatenates before this file; the cache is populated
 *  on first backspace press, well after both modules are loaded.
 *  Single source of truth — adding a function to _CALC_FUNCTIONS
 *  automatically gets smart-backspace coverage. */
function _calcFunctionNamesSorted(){
  if(!_calcFunctionNamesSorted._cache){
    _calcFunctionNamesSorted._cache = Object.keys(_CALC_FUNCTIONS)
      .slice()
      .sort((a, b) => b.length - a.length);
  }
  return _calcFunctionNamesSorted._cache;
}

/** Deletes the atom to the left of the cursor (backspace). Three
 *  branches in order: smart-backspace (function-name + `(` as a
 *  unit), standard char-delete, and template-aware slot boundary
 *  handling. See fix/calc-template-input-cleanup. */
function calcInputBackspace(){
  // 1. Smart-backspace: if the atom just before the cursor is `(`
  // AND the preceding contiguous single-char atoms form a known
  // function name, remove the whole `fname(` in one operation.
  if(CALC_INPUT.cursor.pos > 0){
    const arr = _calcAtomsAt(CALC_INPUT.cursor.path);
    const pos = CALC_INPUT.cursor.pos;
    if(arr[pos - 1] === '('){
      // Walk backward collecting consecutive single-char string atoms.
      let collectStart = pos - 1;
      let collected = '';
      while(collectStart > 0){
        const a = arr[collectStart - 1];
        if(typeof a !== 'string' || a.length !== 1) break;
        collected = a + collected;
        collectStart--;
      }
      if(collected.length > 0){
        const fnNames = _calcFunctionNamesSorted();
        for(const name of fnNames){
          if(collected.endsWith(name)){
            const removeFrom = pos - 1 - name.length;
            arr.splice(removeFrom, name.length + 1);
            CALC_INPUT.cursor.pos = removeFrom;
            return;
          }
        }
      }
      // No fname match — fall through to standard char-delete below.
    }
  }

  // 2. Standard char-delete: one atom to the left of the cursor.
  if(CALC_INPUT.cursor.pos > 0){
    const arr = _calcAtomsAt(CALC_INPUT.cursor.path);
    arr.splice(CALC_INPUT.cursor.pos - 1, 1);
    CALC_INPUT.cursor.pos--;
    return;
  }

  // 3. Template-aware slot-boundary handling. cursor.pos === 0
  // inside a slot. Behavior depends on which slot we're in and
  // whether the template has any content.
  if(CALC_INPUT.cursor.path.length){
    const last = CALC_INPUT.cursor.path[CALC_INPUT.cursor.path.length - 1];
    const parentArr = _calcAtomsAt(CALC_INPUT.cursor.path.slice(0, -1));
    const parentAtom = parentArr[last.idx];

    if(parentAtom && parentAtom.kind && CALC_TEMPLATES[parentAtom.kind]){
      const slotsList = CALC_TEMPLATES[parentAtom.kind].slots;
      const currentSlotIdx = slotsList.indexOf(last.slot);

      if(currentSlotIdx > 0){
        // Non-first slot — walk to previous sibling slot, position
        // at end. Mirrors calcInputLeft's sibling walker. Update
        // the path segment and let _calcAtomsAt normalize the
        // destination slot (it handles arrays, string-backed
        // legacy slots, and missing stubs by writing back a real
        // array). CR PR #122: an earlier "coerce non-array to []"
        // shortcut would have silently wiped string-backed slots.
        const prevSlot = slotsList[currentSlotIdx - 1];
        CALC_INPUT.cursor.path[CALC_INPUT.cursor.path.length - 1] =
          { idx: last.idx, slot: prevSlot };
        const prevSlotArr = _calcAtomsAt(CALC_INPUT.cursor.path);
        CALC_INPUT.cursor.pos = prevSlotArr.length;
        return;
      }

      // First slot, pos=0. If the ENTIRE template is empty (every
      // slot is array-empty, string-empty, or absent), delete the
      // template node entirely. Otherwise no-op — protects the
      // user from accidentally destroying a complex expression
      // with one keystroke. They can empty other slots first, or
      // use AC. Three-shape predicate (CR PR #122): legacy slots
      // may be stored as strings ('12'), arrays (['1','2']), or
      // missing — naive `.length` checks treat string-empty
      // correctly but the original `!slotArr || slotArr.length`
      // would also return false for plain-object stubs whose
      // .length is undefined.
      const allEmpty = slotsList.every(slotName => {
        const s = parentAtom.slots[slotName];
        if(Array.isArray(s))         return s.length === 0;
        if(typeof s === 'string')    return s.length === 0;
        return true;  // missing / stub treated as empty
      });

      if(allEmpty){
        parentArr.splice(last.idx, 1);
        CALC_INPUT.cursor.path.pop();
        CALC_INPUT.cursor.pos = last.idx;
        return;
      }

      // First slot, pos=0, template has content elsewhere — no-op.
      return;
    }

    // Parent isn't a template (shouldn't normally happen given the
    // path-segment model, but stay defensive — preserve the old
    // exit-to-parent behavior).
    const parent = CALC_INPUT.cursor.path.slice(0, -1);
    CALC_INPUT.cursor = { path: parent, pos: last.idx };
  }
}

/** Moves the cursor left. */
function calcInputLeft(){
  if(CALC_INPUT.cursor.pos > 0){
    CALC_INPUT.cursor.pos--;
    // If the atom to the left is a template, step into its last slot
    const arr = _calcAtomsAt(CALC_INPUT.cursor.path);
    const atom = arr[CALC_INPUT.cursor.pos];
    if(atom && typeof atom === 'object' && atom.kind){
      const def = CALC_TEMPLATES[atom.kind];
      const lastSlot = def.slots[def.slots.length - 1];
      const slotArr = atom.slots[lastSlot] = (atom.slots[lastSlot] && typeof atom.slots[lastSlot] === 'object') ? atom.slots[lastSlot] : [];
      CALC_INPUT.cursor.path.push({ idx: CALC_INPUT.cursor.pos, slot: lastSlot });
      CALC_INPUT.cursor.pos = slotArr.length;
    }
  } else if(CALC_INPUT.cursor.path.length){
    // At pos 0 of the current slot. Before exiting to the parent
    // template, check whether there is a previous sibling slot in
    // the same template — if so, step into the end of THAT slot
    // rather than escaping the template entirely. This is what
    // makes multi-slot templates (frac, log, sum, integ, …) usable
    // for left-hand backwards navigation; without it the user
    // would skip every middle slot on their way out.
    const last = CALC_INPUT.cursor.path[CALC_INPUT.cursor.path.length - 1];
    const parentArr = _calcAtomsAt(CALC_INPUT.cursor.path.slice(0, -1));
    const parentAtom = parentArr[last.idx];
    if(parentAtom && parentAtom.kind && CALC_TEMPLATES[parentAtom.kind]){
      const slotsList = CALC_TEMPLATES[parentAtom.kind].slots;
      const currentSlotIdx = slotsList.indexOf(last.slot);
      if(currentSlotIdx > 0){
        const prevSlot = slotsList[currentSlotIdx - 1];
        // Normalize the prev slot's storage the same way the rest
        // of the file does (object/array preferred, defaulting to
        // empty array if missing).
        const prevSlotArr = parentAtom.slots[prevSlot] =
          (parentAtom.slots[prevSlot] && typeof parentAtom.slots[prevSlot] === 'object')
            ? parentAtom.slots[prevSlot]
            : [];
        CALC_INPUT.cursor.path[CALC_INPUT.cursor.path.length - 1] =
          { idx: last.idx, slot: prevSlot };
        CALC_INPUT.cursor.pos = prevSlotArr.length;
        return;
      }
    }
    // First slot (or non-template parent — defensive): exit to parent.
    const parent = CALC_INPUT.cursor.path.slice(0, -1);
    CALC_INPUT.cursor = { path: parent, pos: last.idx };
  }
}

/** Moves the cursor right. */
function calcInputRight(){
  const arr = _calcAtomsAt(CALC_INPUT.cursor.path);
  if(CALC_INPUT.cursor.pos < arr.length){
    const atom = arr[CALC_INPUT.cursor.pos];
    if(atom && typeof atom === 'object' && atom.kind){
      // Step into first slot
      const def = CALC_TEMPLATES[atom.kind];
      const slot = def.slots[0];
      const slotArr = atom.slots[slot] = (atom.slots[slot] && typeof atom.slots[slot] === 'object') ? atom.slots[slot] : [];
      CALC_INPUT.cursor.path.push({ idx: CALC_INPUT.cursor.pos, slot });
      CALC_INPUT.cursor.pos = 0;
    } else {
      CALC_INPUT.cursor.pos++;
    }
  } else if(CALC_INPUT.cursor.path.length){
    // At the end of the current slot's atom array. Before exiting
    // the template, check whether there is a NEXT sibling slot in
    // the same template — this is the missing piece that made
    // multi-slot templates unusable for input (Phase 1 deferred,
    // see docs/calc-redesign/PATCH-calc-ux-redesign-phase1.md).
    const last = CALC_INPUT.cursor.path[CALC_INPUT.cursor.path.length - 1];
    const parentArr = _calcAtomsAt(CALC_INPUT.cursor.path.slice(0, -1));
    const parentAtom = parentArr[last.idx];
    if(parentAtom && parentAtom.kind && CALC_TEMPLATES[parentAtom.kind]){
      const slotsList = CALC_TEMPLATES[parentAtom.kind].slots;
      const currentSlotIdx = slotsList.indexOf(last.slot);
      if(currentSlotIdx >= 0 && currentSlotIdx < slotsList.length - 1){
        const nextSlot = slotsList[currentSlotIdx + 1];
        // Normalize the next slot's storage so subsequent insert
        // calls land in a real array.
        parentAtom.slots[nextSlot] =
          (parentAtom.slots[nextSlot] && typeof parentAtom.slots[nextSlot] === 'object')
            ? parentAtom.slots[nextSlot]
            : [];
        CALC_INPUT.cursor.path[CALC_INPUT.cursor.path.length - 1] =
          { idx: last.idx, slot: nextSlot };
        CALC_INPUT.cursor.pos = 0;
        return;
      }
    }
    // Last slot (or non-template parent — defensive): exit to parent.
    const parent = CALC_INPUT.cursor.path.slice(0, -1);
    CALC_INPUT.cursor = { path: parent, pos: last.idx + 1 };
  }
}

/** Vertical slot chains per template kind. The chain is the
 *  ordered list of slot names that are visually stacked top-down.
 *  Kinds not listed have no vertical chain — Up/Down for those
 *  falls through to history scroll.
 *
 *  mixed deliberately EXCLUDES 'w' (the whole-number part) since
 *  it renders inline to the LEFT of the fraction, not above it.
 *  Only num ↔ den constitute the vertical pair in a mixed number
 *  (CR PR #122 caught the original mixed-w-as-vertical bug). */
const _CALC_VERTICAL_CHAINS = {
  frac:  ['num', 'den'],
  mixed: ['num', 'den'],
};

/** Walks cursor.path bottom-up looking for the nearest ancestor
 *  whose (template kind, slot) is in a vertical chain. Critical
 *  for nested templates: a cursor at frac.num → sqrt.rad should
 *  still respond to Up/Down by navigating the outer frac, not
 *  fall through to history because the last path frame is sqrt
 *  (which has no vertical chain). CR PR #122.
 *
 *  Returns {depth, chain, slotIdx, parentAtom} where depth is
 *  the index in cursor.path of the matched segment, or null if
 *  no vertical ancestor exists at any depth. */
function _calcFindVerticalAncestor(){
  const path = CALC_INPUT.cursor.path;
  for(let depth = path.length - 1; depth >= 0; depth--){
    const seg = path[depth];
    const ancestorPath = path.slice(0, depth);
    const parentArr = _calcAtomsAt(ancestorPath);
    const parentAtom = parentArr[seg.idx];
    if(!parentAtom || !parentAtom.kind) continue;
    const chain = _CALC_VERTICAL_CHAINS[parentAtom.kind];
    if(!chain) continue;
    const slotIdx = chain.indexOf(seg.slot);
    if(slotIdx < 0) continue;
    return { depth, chain, slotIdx, parentAtom };
  }
  return null;
}

/** True when ANY ancestor in cursor.path is a vertically-stacked
 *  template slot. Drives the Up/Down dispatcher's routing
 *  decision — see _calcUpDispatch in calc-ui.js. */
function _calcCursorInVerticalTemplate(){
  return _calcFindVerticalAncestor() !== null;
}

/** Up-arrow: move to the previous slot in the nearest vertical
 *  ancestor's chain. Truncates cursor.path back to the ancestor's
 *  level — any nested templates the cursor was inside are left in
 *  place as content of the source slot. No-op at the top of the
 *  chain. Returns true on transition. */
function calcInputSlotUp(){
  const found = _calcFindVerticalAncestor();
  if(!found) return false;
  if(found.slotIdx <= 0) return false;
  const prevSlot = found.chain[found.slotIdx - 1];
  const idxAtDepth = CALC_INPUT.cursor.path[found.depth].idx;
  // Truncate path back to the ancestor level + update its slot,
  // then let _calcAtomsAt normalize the destination slot in place
  // (handles arrays, string-backed legacy slots, missing stubs).
  // CR PR #122: an earlier "coerce non-array to []" shortcut
  // would have wiped string-backed slot contents on hop.
  CALC_INPUT.cursor.path = CALC_INPUT.cursor.path.slice(0, found.depth);
  CALC_INPUT.cursor.path.push({ idx: idxAtDepth, slot: prevSlot });
  const prevSlotArr = _calcAtomsAt(CALC_INPUT.cursor.path);
  CALC_INPUT.cursor.pos = prevSlotArr.length;
  return true;
}

/** Down-arrow: move to the next slot in the nearest vertical
 *  ancestor's chain. Same truncation behavior as slotUp. No-op
 *  at the bottom of the chain. */
function calcInputSlotDown(){
  const found = _calcFindVerticalAncestor();
  if(!found) return false;
  if(found.slotIdx >= found.chain.length - 1) return false;
  const nextSlot = found.chain[found.slotIdx + 1];
  const idxAtDepth = CALC_INPUT.cursor.path[found.depth].idx;
  CALC_INPUT.cursor.path = CALC_INPUT.cursor.path.slice(0, found.depth);
  CALC_INPUT.cursor.path.push({ idx: idxAtDepth, slot: nextSlot });
  // _calcAtomsAt normalizes string-backed / stub slots in place;
  // pos:0 lands at start of the (now-array) next slot.
  _calcAtomsAt(CALC_INPUT.cursor.path);
  CALC_INPUT.cursor.pos = 0;
  return true;
}

/** Inserts a template at the cursor, then parks cursor in its first slot. */
function calcInputInsertTemplate(kind){
  const def = CALC_TEMPLATES[kind];
  if(!def) return;
  const node = { kind, slots: {} };
  def.slots.forEach(s => node.slots[s] = []);
  const arr = _calcAtomsAt(CALC_INPUT.cursor.path);
  arr.splice(CALC_INPUT.cursor.pos, 0, node);
  // Park cursor in the first slot
  const first = def.slots[0];
  const pathSeg = { idx: CALC_INPUT.cursor.pos, slot: first };
  CALC_INPUT.cursor.path.push(pathSeg);
  CALC_INPUT.cursor.pos = 0;
}

/* ── SERIALIZATION ───────────────────────────────────────────── */

/** Serializes atom array to an evaluator-ready string. Calculus templates
 *  (sum/prod/integ/deriv) register opaque placeholder IDs here that the
 *  evaluator resolves before tokenization. This form is NOT safe for
 *  persistence or display — use calcSerializeDisplay for history entries. */
function calcSerialize(atoms){
  if(!atoms) atoms = CALC_INPUT.atoms;
  let out = '';
  for(const a of atoms){
    if(typeof a === 'string'){ out += a; continue; }
    if(a && a.kind){
      const def = CALC_TEMPLATES[a.kind];
      if(!def){ continue; }
      const slotStrs = {};
      def.slots.forEach(s => slotStrs[s] = calcSerialize(a.slots[s]));
      out += def.serialize(slotStrs);
    }
  }
  return out;
}

/** Serializes atom array to a stable, human-readable string — never emits
 *  placeholder tokens. Templates that define `display(slots)` use that;
 *  others fall back to their normal `serialize`. Use this for anything that
 *  outlives a single evaluate() call (history entries, session snapshots). */
function calcSerializeDisplay(atoms){
  if(!atoms) atoms = CALC_INPUT.atoms;
  let out = '';
  for(const a of atoms){
    if(typeof a === 'string'){ out += a; continue; }
    if(a && a.kind){
      const def = CALC_TEMPLATES[a.kind];
      if(!def){ continue; }
      const slotStrs = {};
      def.slots.forEach(s => slotStrs[s] = calcSerializeDisplay(a.slots[s]));
      out += (def.display || def.serialize)(slotStrs);
    }
  }
  return out;
}

/* ── RENDER ──────────────────────────────────────────────────── */

/** Display-only glyph map. Storage + serialization keep ASCII operators
 *  (* / -) so the tokenizer and history replay stay unchanged; the render
 *  path substitutes the proper math glyphs (× ÷ −) so users don't see
 *  asterisks and slashes in the live input area. */
const _CALC_DISPLAY_GLYPH = { '*': '×', '/': '÷', '-': '−' };

/** Transform an arbitrary already-serialized calculator string into
 *  display form by substituting the operator glyphs. Used for history
 *  rows and any other surface that renders a pre-flattened expression
 *  string (as opposed to the atom array, which calcRender handles).
 *  Kept as a pure function so callers can compose with _escCalc /
 *  escHtml without worrying about double-encoding — glyphify first,
 *  then escape. */
function calcDisplayGlyphify(s){
  if(s == null) return '';
  // Replace only exact ASCII operators. We deliberately don't touch
  // `-` inside identifiers (there aren't any) or `/` inside a fraction
  // placeholder notation like "()/()" because the whole segment is
  // the serialized form — any `/` in it IS division.
  return String(s).replace(/[*/\-]/g, ch => _CALC_DISPLAY_GLYPH[ch] || ch);
}

/** Renders atom array to HTML, with a caret marker at cursor position. */
function calcRender(atoms, path, cursorPos, includeCaret){
  if(!atoms) atoms = CALC_INPUT.atoms;
  const escHtml = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  let out = '';
  for(let i = 0; i < atoms.length; i++){
    if(includeCaret && _pathsEqual(path, CALC_INPUT.cursor.path) && i === cursorPos){
      out += '<span class="ct-caret"></span>';
    }
    const a = atoms[i];
    if(typeof a === 'string'){
      const g = _CALC_DISPLAY_GLYPH[a];
      out += g ? escHtml(g) : escHtml(a);
      continue;
    }
    if(a && a.kind){
      const def = CALC_TEMPLATES[a.kind];
      if(!def){ continue; }
      const slotHtml = {};
      def.slots.forEach(slot => {
        const inside = a.slots[slot] || [];
        const childPath = (path || []).concat([{ idx: i, slot }]);
        // Empty slot — special-case so the focused-slot indicator
        // and the caret can coexist. The existing fallback path
        // (`childHtml || '<span class="ct-empty">▢</span>'`) hid
        // the placeholder square whenever the caret was inside an
        // empty slot, because the caret span itself is non-empty
        // truthy HTML. Users couldn't see which slot they were in
        // until they typed a character.
        if(inside.length === 0){
          const isFocused = includeCaret &&
            _pathsEqual(childPath, CALC_INPUT.cursor.path);
          const cls = isFocused ? 'ct-empty is-focused' : 'ct-empty';
          // No caret in this branch — the .is-focused accent border
          // IS the cursor indicator for empty slots. The previous
          // version emitted a caret beside the ▢ box, which read
          // as two cursor positions per recording-use feedback.
          // See fix/calc-template-input-cleanup.
          slotHtml[slot] = `<span class="${cls}">▢</span>`;
        } else {
          slotHtml[slot] = calcRender(inside, childPath, cursorPos, includeCaret);
        }
      });
      out += def.render(slotHtml);
    }
  }
  if(includeCaret && _pathsEqual(path, CALC_INPUT.cursor.path) && cursorPos === atoms.length){
    out += '<span class="ct-caret"></span>';
  }
  return out;
}

function _pathsEqual(a, b){
  a = a || []; b = b || [];
  if(a.length !== b.length) return false;
  for(let i = 0; i < a.length; i++){
    if(a[i].idx !== b[i].idx || a[i].slot !== b[i].slot) return false;
  }
  return true;
}

/** Flattens root-level atoms and caret-visible render at current cursor. */
function calcRenderCurrent(){
  return calcRender(CALC_INPUT.atoms, [], CALC_INPUT.cursor.pos, true);
}

