/* ==== src/js/features/calc/calc-undo.js ==== */
/* features/calc/calc-undo.js — UNDO / REDO for the Calculate-mode input.
   Phase 2 of the calc redesign; the buttons existed since Phase 1 but hit the
   console.log stub in _calcV2HandleAct.

   WHAT IS UNDOABLE
   Only the live input — CALC_INPUT.atoms plus the cursor. Typing, deletions,
   template insertions, DMS symbol insertion, ± and ×10ⁿ: anything that changes
   the expression you are building. Deliberately NOT undoable:
     - evaluated history entries (EXE is a commit point, see below),
     - settings (angle, format), panels, or anything in CALC_STATE,
     - anything across a session — the stack is in-memory only and is never
       persisted, so a reload starts clean.

   HOW CHANGES ARE DETECTED
   Rather than enumerating which keys mutate — a list that silently rots as keys
   are added — the keypad dispatcher captures a snapshot BEFORE the key runs and
   commits it on the next microtask, keeping it only if the input actually
   changed. Every mutation path is covered automatically, including future ones,
   and keys that don't touch the input record nothing.

   MEMORY
   Snapshots are JSON strings of {atoms, cursor}. The stack is bounded at
   CALC_UNDO_MAX entries (oldest dropped), so a long recording session cannot
   grow it without limit. EXE and AC reset both stacks: they are clean-slate
   boundaries, and undoing "backwards through" an evaluation into a previous
   expression would contradict the input-level scope above. */

/** Hard cap on remembered input states. 50 covers any realistic edit run while
 *  keeping the stack trivially small (each entry is a short JSON string). */
const CALC_UNDO_MAX = 50;

const _CALC_UNDO = {
  undo: [],        // snapshots of states we can go BACK to (oldest → newest)
  redo: [],        // snapshots we can go FORWARD to after undoing
  applying: false, // guard: an undo/redo must not record itself as an edit
};

/* Suppress the dispatcher's PENDING commit as well as the current call.
 *
 * UNDO, REDO and the EXE/AC resets all run from inside the keypad click
 * handler, which captured a snapshot before dispatch and queued a commit for
 * the next microtask. A guard that cleared synchronously was still false by the
 * time that commit ran, so undo re-recorded its own change (every UNDO pushed a
 * new entry and the stack walked in circles) and EXE's reset was immediately
 * followed by a push, leaving depth 1 instead of 0 — both measured.
 *
 * Clearing the flag from a microtask queued HERE means it is cleared strictly
 * after the dispatcher's commit microtask, which was queued first. */
function _calcUndoSuppress(){
  _CALC_UNDO.applying = true;
  queueMicrotask(() => { _CALC_UNDO.applying = false; });
}

/** Serializes the live input. Doubles as the change-detection key — atoms are
 *  plain data (chars, or {kind, slots} template nodes) and the cursor is
 *  {path, pos}, so JSON round-trips them exactly and compares reliably. */
function _calcUndoSnapshot(){
  try{
    return JSON.stringify({ atoms: CALC_INPUT.atoms, cursor: CALC_INPUT.cursor });
  }catch(_){
    return null;   // never let snapshotting break a keypress
  }
}

/** Replaces the live input with a snapshot. */
function _calcUndoRestore(snap){
  let o;
  try{ o = JSON.parse(snap); }catch(_){ return false; }
  if(!o || !Array.isArray(o.atoms)) return false;
  CALC_INPUT.atoms  = o.atoms;
  CALC_INPUT.cursor = (o.cursor && Array.isArray(o.cursor.path))
    ? o.cursor
    : { path: [], pos: o.atoms.length };
  return true;
}

/** Called by the keypad dispatcher BEFORE a key runs. Returns the pre-key
 *  snapshot, or null when recording is suppressed. */
function calcUndoCapture(){
  if(_CALC_UNDO.applying) return null;
  return _calcUndoSnapshot();
}

/** Called on the microtask after a key ran. Keeps `before` only if the key
 *  actually changed the input. */
function calcUndoCommit(before){
  if(before == null || _CALC_UNDO.applying) return;
  const after = _calcUndoSnapshot();
  if(after == null || after === before) return;     // no edit → no entry
  _CALC_UNDO.undo.push(before);
  // Bounded: drop the oldest rather than growing without limit.
  while(_CALC_UNDO.undo.length > CALC_UNDO_MAX) _CALC_UNDO.undo.shift();
  // A fresh edit invalidates the redo branch, as in every editor.
  _CALC_UNDO.redo.length = 0;
}

/** Clears both stacks. Called at clean-slate boundaries (EXE, AC). */
function calcUndoReset(){
  _CALC_UNDO.undo.length = 0;
  _CALC_UNDO.redo.length = 0;
  _calcUndoSuppress();   // the EXE/AC keypress itself must not re-push
}

/** True when there is anything to undo / redo — drives the disabled state. */
function calcCanUndo(){ return _CALC_UNDO.undo.length > 0; }
function calcCanRedo(){ return _CALC_UNDO.redo.length > 0; }

/** Steps one state back. Returns true if something changed. */
function calcUndo(){
  if(!_CALC_UNDO.undo.length) return false;
  const current = _calcUndoSnapshot();
  const prev = _CALC_UNDO.undo.pop();
  _calcUndoSuppress();
  const ok = _calcUndoRestore(prev);
  if(!ok) return false;
  if(current != null) _CALC_UNDO.redo.push(current);
  while(_CALC_UNDO.redo.length > CALC_UNDO_MAX) _CALC_UNDO.redo.shift();
  return true;
}

/** Steps one state forward. Returns true if something changed. */
function calcRedo(){
  if(!_CALC_UNDO.redo.length) return false;
  const current = _calcUndoSnapshot();
  const next = _CALC_UNDO.redo.pop();
  _calcUndoSuppress();
  const ok = _calcUndoRestore(next);
  if(!ok) return false;
  if(current != null) _CALC_UNDO.undo.push(current);
  while(_CALC_UNDO.undo.length > CALC_UNDO_MAX) _CALC_UNDO.undo.shift();
  return true;
}

