/* ==== src/js/features/calc/calc-stats.js ==== */
/* features/calc/calc-stats.js — Statistics mode (fx-8200 style)
   1-variable: mean, sample stdev, population stdev, Σx, Σx², min, max,
               median, Q1, Q3, variance.
   2-variable: linear regression y = a + bx, correlation r, r².
   Data is stored in CALC_STATS_STATE.rows — each row is { x, y, freq }.
   `freq` defaults to 1 (used when binning or weighting data).
   The UI renders a table with editable cells; bottom panel shows the
   computed statistics. Pressing `Calc` re-evaluates them. */

/** Factory for the default Statistics state shape. Used both by the
 *  module's initializer and by reset paths (widgetState.js,
 *  persistence.js) so "New Session" and snapshot restore share a single
 *  source of truth. */
function _calcStatsDefaults(){
  return {
    mode: '1var',                            // '1var' | '2var'
    rows: [
      { x:'', y:'', freq:'1' },
      { x:'', y:'', freq:'1' },
      { x:'', y:'', freq:'1' }
    ],
    results: null                            // cached last computation
  };
}

const CALC_STATS_STATE = _calcStatsDefaults();

/** Resets the runtime Statistics state in place. Called from
 *  resetWidgetState and applySessionSnapshot so both reset and restore
 *  paths stay aligned. */
function resetCalcStatsState(){
  const d = _calcStatsDefaults();
  CALC_STATS_STATE.mode    = d.mode;
  CALC_STATS_STATE.rows    = d.rows;
  CALC_STATS_STATE.results = d.results;
}

/** Parses a numeric cell, returning null when empty/invalid. */
function _statsParseCell(v){
  if(v == null) return null;
  const s = String(v).trim();
  if(!s) return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

/** Resets the stats grid to three empty rows (keeps current mode). */
function calcStatsClearRows(){
  const d = _calcStatsDefaults();
  CALC_STATS_STATE.rows    = d.rows;
  CALC_STATS_STATE.results = null;
}

/** Computes 1-variable statistics from the current rows. Returns null if
 *  no valid data points are present. */
function calcStats1Var(){
  const data = [];
  for(const r of CALC_STATS_STATE.rows){
    const x = _statsParseCell(r.x);
    const f = _statsParseCell(r.freq);
    if(x == null || f == null || f <= 0) continue;
    // Expand frequency into individual observations (capped to avoid blowup)
    const count = Math.min(Math.round(f), 1e5);
    for(let i = 0; i < count; i++) data.push(x);
  }
  if(!data.length) return null;
  const n    = data.length;
  const sum  = data.reduce((a, b) => a + b, 0);
  const sum2 = data.reduce((a, b) => a + b * b, 0);
  const mean = sum / n;
  const varPop = sum2 / n - mean * mean;
  const varSmp = n > 1 ? (sum2 - n * mean * mean) / (n - 1) : 0;
  const sorted = [...data].sort((a, b) => a - b);
  const q = p => {
    const idx = (sorted.length - 1) * p;
    const lo  = Math.floor(idx);
    const hi  = Math.ceil(idx);
    if(lo === hi) return sorted[lo];
    return sorted[lo] + (sorted[hi] - sorted[lo]) * (idx - lo);
  };
  return {
    n,
    sumX:   sum,
    sumX2:  sum2,
    mean,
    sigmaX: Math.sqrt(Math.max(0, varPop)),
    sX:     Math.sqrt(Math.max(0, varSmp)),
    min:    sorted[0],
    max:    sorted[sorted.length - 1],
    median: q(0.5),
    q1:     q(0.25),
    q3:     q(0.75)
  };
}

/** Computes 2-variable linear regression + correlation. */
function calcStats2Var(){
  const pairs = [];
  for(const r of CALC_STATS_STATE.rows){
    const x = _statsParseCell(r.x);
    const y = _statsParseCell(r.y);
    if(x == null || y == null) continue;
    pairs.push([x, y]);
  }
  if(pairs.length < 2) return null;
  const n = pairs.length;
  let sumX = 0, sumY = 0, sumX2 = 0, sumY2 = 0, sumXY = 0;
  for(const [x, y] of pairs){
    sumX  += x;
    sumY  += y;
    sumX2 += x * x;
    sumY2 += y * y;
    sumXY += x * y;
  }
  const meanX = sumX / n;
  const meanY = sumY / n;
  const ssxx  = sumX2 - n * meanX * meanX;
  const ssyy  = sumY2 - n * meanY * meanY;
  const ssxy  = sumXY - n * meanX * meanY;
  const b = ssxx ? ssxy / ssxx : 0;
  const a = meanY - b * meanX;
  const r = (ssxx * ssyy > 0) ? ssxy / Math.sqrt(ssxx * ssyy) : 0;
  return {
    n, sumX, sumY, sumX2, sumY2, sumXY,
    meanX, meanY,
    a, b,
    r,
    r2: r * r,
    // Predictors (useful for forecasting):
    yAt: x => a + b * x,
    xAt: y => (b ? (y - a) / b : NaN)
  };
}

function _statsFmt(v){
  if(v == null || Number.isNaN(v)) return '—';
  if(typeof calcFormatResult === 'function') return calcFormatResult(v);
  return String(v);
}

/** Renders the Statistics mode UI. */
function calcRenderStats(){
  const rows = CALC_STATS_STATE.rows;
  const is2 = CALC_STATS_STATE.mode === '2var';
  const res = CALC_STATS_STATE.results;
  const fs = CALC_STATE.fullscreen ? ' calc-fs' : '';

  const headCells = is2
    ? `<th>x</th><th>y</th>`
    : `<th>x</th><th>freq</th>`;
  const bodyCells = rows.map((r, i) => is2
    ? `<tr><td>${i+1}</td><td><input class="st-cell" data-row="${i}" data-col="x" value="${_escCalc(r.x)}" inputmode="decimal"></td><td><input class="st-cell" data-row="${i}" data-col="y" value="${_escCalc(r.y)}" inputmode="decimal"></td></tr>`
    : `<tr><td>${i+1}</td><td><input class="st-cell" data-row="${i}" data-col="x" value="${_escCalc(r.x)}" inputmode="decimal"></td><td><input class="st-cell" data-row="${i}" data-col="freq" value="${_escCalc(r.freq)}" inputmode="decimal"></td></tr>`
  ).join('');

  let resultsHtml = '<div class="st-empty">Add data and press Calc</div>';
  if(res){
    if(is2){
      resultsHtml = `
        <div class="st-grid">
          <div><span class="st-k">n</span><span class="st-v">${_statsFmt(res.n)}</span></div>
          <div><span class="st-k">x̄</span><span class="st-v">${_statsFmt(res.meanX)}</span></div>
          <div><span class="st-k">ȳ</span><span class="st-v">${_statsFmt(res.meanY)}</span></div>
          <div><span class="st-k">a</span><span class="st-v">${_statsFmt(res.a)}</span></div>
          <div><span class="st-k">b</span><span class="st-v">${_statsFmt(res.b)}</span></div>
          <div><span class="st-k">r</span><span class="st-v">${_statsFmt(res.r)}</span></div>
          <div><span class="st-k">r²</span><span class="st-v">${_statsFmt(res.r2)}</span></div>
          <div><span class="st-k">Σxy</span><span class="st-v">${_statsFmt(res.sumXY)}</span></div>
        </div>
        <div class="st-eq">y = ${_statsFmt(res.a)} + ${_statsFmt(res.b)}·x</div>`;
    } else {
      resultsHtml = `
        <div class="st-grid">
          <div><span class="st-k">n</span><span class="st-v">${_statsFmt(res.n)}</span></div>
          <div><span class="st-k">x̄</span><span class="st-v">${_statsFmt(res.mean)}</span></div>
          <div><span class="st-k">σx</span><span class="st-v">${_statsFmt(res.sigmaX)}</span></div>
          <div><span class="st-k">sx</span><span class="st-v">${_statsFmt(res.sX)}</span></div>
          <div><span class="st-k">Σx</span><span class="st-v">${_statsFmt(res.sumX)}</span></div>
          <div><span class="st-k">Σx²</span><span class="st-v">${_statsFmt(res.sumX2)}</span></div>
          <div><span class="st-k">min</span><span class="st-v">${_statsFmt(res.min)}</span></div>
          <div><span class="st-k">max</span><span class="st-v">${_statsFmt(res.max)}</span></div>
          <div><span class="st-k">Q1</span><span class="st-v">${_statsFmt(res.q1)}</span></div>
          <div><span class="st-k">med</span><span class="st-v">${_statsFmt(res.median)}</span></div>
          <div><span class="st-k">Q3</span><span class="st-v">${_statsFmt(res.q3)}</span></div>
        </div>`;
    }
  }

  return `
    <div class="calc-wrap calc-stats${fs}">
      <div class="calc-hdr">
        <button class="calc-home-btn" data-hgl-action="home" title="Home"><span class="ms">apps</span></button>
        <span class="calc-brand hf">Statistics</span>
        <button class="calc-x" data-hgl-action="close" title="Close"><span class="ms">close</span></button>
      </div>
      <div class="st-modebar">
        <button class="st-pill${is2 ? '' : ' on'}" data-act="mode-1var">1-Var</button>
        <button class="st-pill${is2 ? ' on' : ''}" data-act="mode-2var">2-Var</button>
        <div style="flex:1"></div>
        <button class="st-btn" data-act="add">+ Row</button>
        <button class="st-btn" data-act="clear">Clear</button>
        <button class="st-btn st-btn-p" data-act="calc">Calc</button>
      </div>
      <div class="st-table">
        <table><thead><tr><th>#</th>${headCells}</tr></thead>
        <tbody>${bodyCells}</tbody></table>
      </div>
      <div class="st-results">${resultsHtml}</div>
    </div>`;
}

/** Wires input/button handlers for the Statistics mode. */
function calcWireStats(){
  const panel = document.querySelector('#calc-p .calc-stats');
  if(!panel || panel._wired) return;
  panel._wired = true;

  panel.addEventListener('input', e => {
    const cell = e.target.closest('.st-cell');
    if(!cell) return;
    const row = +cell.dataset.row;
    const col = cell.dataset.col;
    if(CALC_STATS_STATE.rows[row]) CALC_STATS_STATE.rows[row][col] = cell.value;
    if(typeof scheduleAutosave === 'function') scheduleAutosave();
  });

  panel.addEventListener('click', e => {
    const btn = e.target.closest('[data-act]');
    if(!btn) return;
    switch(btn.dataset.act){
      case 'mode-1var': CALC_STATS_STATE.mode = '1var'; CALC_STATS_STATE.results = null; calcRenderUI(); break;
      case 'mode-2var': CALC_STATS_STATE.mode = '2var'; CALC_STATS_STATE.results = null; calcRenderUI(); break;
      case 'add':
        CALC_STATS_STATE.rows.push({ x:'', y:'', freq:'1' });
        calcRenderUI();
        break;
      case 'clear':
        calcStatsClearRows();
        calcRenderUI();
        if(typeof scheduleAutosave === 'function') scheduleAutosave();
        break;
      case 'calc':
        CALC_STATS_STATE.results = CALC_STATS_STATE.mode === '2var'
          ? calcStats2Var()
          : calcStats1Var();
        calcRenderUI();
        if(typeof scheduleAutosave === 'function') scheduleAutosave();
        break;
    }
  });
}

;
/* ==== src/js/features/calc/calc-dist.js ==== */
/* features/calc/calc-dist.js — Distribution mode
   Probability distributions (fx-8200 style):
     Normal:   PDF, CDF(lower,upper), InvN(p)  with mean μ, stdev σ
     Binomial: PDF(k), CDF(k)                  with n trials, prob p
     Poisson:  PDF(k), CDF(k)                  with rate λ
   All use closed-form or series implementations — no lookup tables.
   CDFs for continuous distributions are computed via erf; binomial and
   poisson CDFs use cumulative summation of their PDFs. */

/** Factory for the default Distribution state shape. Shared between the
 *  module's initializer, reset paths (widgetState.js), and snapshot
 *  restore (persistence.js) so all three stay aligned. */
function _calcDistDefaults(){
  return {
    type: 'normal',        // 'normal' | 'binom' | 'poisson'
    op:   'pdf',           // 'pdf' | 'cdf' | 'invN' (normal only)
    params: {
      mean:  '0',
      stdev: '1',
      x:     '0',
      lower: '-1',
      upper: '1',
      p:     '0.5',
      n:     '10',
      prob:  '0.5',
      k:     '5',
      lambda:'3'
    },
    result: null
  };
}

const CALC_DIST_STATE = _calcDistDefaults();

/** Resets the runtime Distribution state in place. Called from
 *  resetWidgetState and applySessionSnapshot. */
function resetCalcDistState(){
  const d = _calcDistDefaults();
  CALC_DIST_STATE.type   = d.type;
  CALC_DIST_STATE.op     = d.op;
  CALC_DIST_STATE.params = d.params;
  CALC_DIST_STATE.result = d.result;
}

/** Returns a fresh copy of the canonical param defaults. Exposed so the
 *  persistence whitelist-merge can iterate known keys without duplicating
 *  the defaults inline. */
function getCalcDistParamDefaults(){
  return _calcDistDefaults().params;
}

/* ── DISTRIBUTION MATH ───────────────────────────────────────── */

/** Abramowitz & Stegun 7.1.26 — max error ≈ 1.5e-7 for erf. Good enough
 *  for a classroom calculator. Uses sign-extending form for negative x. */
function _distErf(x){
  const sign = x < 0 ? -1 : 1;
  const a = Math.abs(x);
  const t = 1 / (1 + 0.3275911 * a);
  const y = 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-a * a);
  return sign * y;
}

function _distNormalPDF(x, mu, sigma){
  if(sigma <= 0) return NaN;
  const z = (x - mu) / sigma;
  return Math.exp(-0.5 * z * z) / (sigma * Math.sqrt(2 * Math.PI));
}

function _distNormalCDF(x, mu, sigma){
  if(sigma <= 0) return NaN;
  return 0.5 * (1 + _distErf((x - mu) / (sigma * Math.SQRT2)));
}

/** Inverse standard normal — Beasley-Springer/Moro algorithm. Input in
 *  (0,1). Returns z such that P(Z <= z) = p. */
function _distInvNormStd(p){
  if(p <= 0 || p >= 1) return NaN;
  // Rational approximation, max error ~1e-9 across (0,1)
  const a = [-3.969683028665376e1, 2.209460984245205e2, -2.759285104469687e2,
             1.383577518672690e2, -3.066479806614716e1, 2.506628277459239];
  const b = [-5.447609879822406e1, 1.615858368580409e2, -1.556989798598866e2,
             6.680131188771972e1, -1.328068155288572e1];
  const c = [-7.784894002430293e-3, -3.223964580411365e-1, -2.400758277161838,
             -2.549732539343734, 4.374664141464968, 2.938163982698783];
  const d = [7.784695709041462e-3, 3.224671290700398e-1, 2.445134137142996,
             3.754408661907416];
  const plow  = 0.02425;
  const phigh = 1 - plow;
  let q, r;
  if(p < plow){
    q = Math.sqrt(-2 * Math.log(p));
    return (((((c[0]*q + c[1])*q + c[2])*q + c[3])*q + c[4])*q + c[5]) /
           ((((d[0]*q + d[1])*q + d[2])*q + d[3])*q + 1);
  }
  if(p <= phigh){
    q = p - 0.5;
    r = q * q;
    return (((((a[0]*r + a[1])*r + a[2])*r + a[3])*r + a[4])*r + a[5]) * q /
           (((((b[0]*r + b[1])*r + b[2])*r + b[3])*r + b[4])*r + 1);
  }
  q = Math.sqrt(-2 * Math.log(1 - p));
  return -(((((c[0]*q + c[1])*q + c[2])*q + c[3])*q + c[4])*q + c[5]) /
          ((((d[0]*q + d[1])*q + d[2])*q + d[3])*q + 1);
}

function _distInvNorm(p, mu, sigma){
  if(sigma <= 0) return NaN;
  return mu + sigma * _distInvNormStd(p);
}

function _distBinomPDF(k, n, p){
  k = Math.round(k); n = Math.round(n);
  // Reject non-finite inputs up front — calcEvaluate can return ±Infinity
  // for expressions like 1/0, which would otherwise run the factorial
  // loop below forever and lock the UI thread.
  if(!Number.isFinite(k) || !Number.isFinite(n) || !Number.isFinite(p) ||
     n < 0 || p < 0 || p > 1) return NaN;
  if(k < 0 || k > n) return 0;
  // Use log-factorial to avoid overflow for larger n
  const lnFact = m => {
    let s = 0;
    for(let i = 2; i <= m; i++) s += Math.log(i);
    return s;
  };
  const logC = lnFact(n) - lnFact(k) - lnFact(n - k);
  const logP = k === 0 ? 0 : k * Math.log(p);
  const logQ = (n - k) === 0 ? 0 : (n - k) * Math.log(1 - p);
  return Math.exp(logC + logP + logQ);
}

/** O(k) binomial CDF via the PMF recurrence
 *    P(i+1) = P(i) · (n−i)/(i+1) · p/(1−p)
 *  Computes P(X=0) = (1−p)^n once via log1p (accurate for small p) and
 *  walks up to k without re-running lnFact each term. Large n/k inputs
 *  no longer stall the main thread. */
function _distBinomCDF(k, n, p){
  k = Math.round(k); n = Math.round(n);
  if(!Number.isFinite(k) || !Number.isFinite(n) || n < 0 || p < 0 || p > 1) return NaN;
  if(k < 0)    return 0;
  if(k >= n)   return 1;
  if(p === 0)  return 1;                    // all mass at 0
  if(p === 1)  return k >= n ? 1 : 0;       // all mass at n
  let term = Math.exp(n * Math.log1p(-p));  // P(X = 0)
  let acc  = term;
  const ratio = p / (1 - p);
  for(let i = 0; i < k; i++){
    term *= ((n - i) / (i + 1)) * ratio;
    acc  += term;
  }
  return Math.min(1, acc);
}

function _distPoissonPDF(k, lambda){
  k = Math.round(k);
  // Same Infinity guard as the binomial PDF — otherwise an infinite k
  // would spin the logFact loop below indefinitely.
  if(!Number.isFinite(k) || !Number.isFinite(lambda) || lambda < 0) return NaN;
  if(k < 0) return 0;
  // e^-λ * λ^k / k!   — computed via logs for large k/λ
  let logFact = 0;
  for(let i = 2; i <= k; i++) logFact += Math.log(i);
  return Math.exp(-lambda + k * Math.log(lambda || 1e-300) - logFact);
}

/** O(k) Poisson CDF via the PMF recurrence P(i+1) = P(i) · λ/(i+1).
 *  Avoids the inner logFact rebuild each term so classroom-scale λ/k
 *  don't stall the UI. */
function _distPoissonCDF(k, lambda){
  k = Math.round(k);
  if(!Number.isFinite(k) || !Number.isFinite(lambda) || lambda < 0) return NaN;
  if(k < 0) return 0;
  let term = Math.exp(-lambda);             // P(X = 0)
  let acc  = term;
  for(let i = 0; i < k; i++){
    term *= lambda / (i + 1);
    acc  += term;
  }
  return Math.min(1, acc);
}

/* ── UI ──────────────────────────────────────────────────────── */

/** Evaluates a param string through the main evaluator so expressions
 *  like pi, sqrt(2), 2^10 can be used as parameters. */
function _distEvalParam(s){
  if(typeof calcEvaluate !== 'function') return Number(s);
  const r = calcEvaluate(String(s || ''));
  return r.ok && r.value != null ? r.value : NaN;
}

function _distCompute(){
  const P = CALC_DIST_STATE.params;
  const t = CALC_DIST_STATE.type;
  const op = CALC_DIST_STATE.op;
  try {
    if(t === 'normal'){
      const mu    = _distEvalParam(P.mean);
      const sigma = _distEvalParam(P.stdev);
      if(op === 'pdf'){
        const x = _distEvalParam(P.x);
        return { value: _distNormalPDF(x, mu, sigma), label: `f(x = ${x})` };
      }
      if(op === 'cdf'){
        const lo = _distEvalParam(P.lower);
        const hi = _distEvalParam(P.upper);
        // Normalize reversed bounds so the interval probability can't go
        // negative when the user enters lower > upper.
        const a = Math.min(lo, hi);
        const b = Math.max(lo, hi);
        return { value: _distNormalCDF(b, mu, sigma) - _distNormalCDF(a, mu, sigma),
                 label: `P(${a} ≤ X ≤ ${b})` };
      }
      if(op === 'invN'){
        const p = _distEvalParam(P.p);
        return { value: _distInvNorm(p, mu, sigma), label: `x where P(X ≤ x) = ${p}` };
      }
    }
    if(t === 'binom'){
      const n    = _distEvalParam(P.n);
      const prob = _distEvalParam(P.prob);
      const k    = _distEvalParam(P.k);
      if(op === 'pdf') return { value: _distBinomPDF(k, n, prob), label: `P(X = ${Math.round(k)})` };
      if(op === 'cdf') return { value: _distBinomCDF(k, n, prob), label: `P(X ≤ ${Math.round(k)})` };
    }
    if(t === 'poisson'){
      const lambda = _distEvalParam(P.lambda);
      const k      = _distEvalParam(P.k);
      if(op === 'pdf') return { value: _distPoissonPDF(k, lambda), label: `P(X = ${Math.round(k)})` };
      if(op === 'cdf') return { value: _distPoissonCDF(k, lambda), label: `P(X ≤ ${Math.round(k)})` };
    }
  } catch(e){
    return { value: NaN, label: 'Error: ' + e.message };
  }
  return { value: NaN, label: 'Unsupported combination' };
}

function _distParamInput(key, label, col){
  const v = CALC_DIST_STATE.params[key] || '';
  // No inputmode="decimal": params accept full calc expressions (pi,
  // sqrt(2), 2^10) that require letters and operators on mobile keyboards.
  return `<label class="dt-p"><span class="dt-plabel">${label}</span><input class="dt-pinput" data-pkey="${key}" value="${_escCalc(v)}"${col?` style="grid-column:${col};"`:''}></label>`;
}

function _distRenderParams(){
  const t  = CALC_DIST_STATE.type;
  const op = CALC_DIST_STATE.op;
  if(t === 'normal'){
    const common = _distParamInput('mean','μ') + _distParamInput('stdev','σ');
    if(op === 'pdf')  return common + _distParamInput('x','x');
    if(op === 'cdf')  return common + _distParamInput('lower','lower') + _distParamInput('upper','upper');
    if(op === 'invN') return common + _distParamInput('p','p');
  }
  if(t === 'binom'){
    return _distParamInput('n','n') + _distParamInput('prob','p') + _distParamInput('k','k');
  }
  if(t === 'poisson'){
    return _distParamInput('lambda','λ') + _distParamInput('k','k');
  }
  return '';
}

function _distOpsFor(type){
  if(type === 'normal') return [
    { id:'pdf', label:'PDF' }, { id:'cdf', label:'CDF' }, { id:'invN', label:'InvN' }
  ];
  return [ { id:'pdf', label:'PDF' }, { id:'cdf', label:'CDF' } ];
}

/** Renders the Distribution mode UI. */
function calcRenderDist(){
  const fs = CALC_STATE.fullscreen ? ' calc-fs' : '';
  const t  = CALC_DIST_STATE.type;
  const op = CALC_DIST_STATE.op;
  const types = [
    { id:'normal',  label:'Normal'   },
    { id:'binom',   label:'Binomial' },
    { id:'poisson', label:'Poisson'  }
  ];
  const typePills = types.map(x =>
    `<button class="st-pill${t === x.id ? ' on':''}" data-act="type-${x.id}">${x.label}</button>`
  ).join('');
  const opPills = _distOpsFor(t).map(x =>
    `<button class="st-pill${op === x.id ? ' on':''}" data-act="op-${x.id}">${x.label}</button>`
  ).join('');
  const res = CALC_DIST_STATE.result;

  return `
    <div class="calc-wrap calc-dist${fs}">
      <div class="calc-hdr">
        <button class="calc-home-btn" data-hgl-action="home" title="Home"><span class="ms">apps</span></button>
        <span class="calc-brand hf">Distribution</span>
        <button class="calc-x" data-hgl-action="close" title="Close"><span class="ms">close</span></button>
      </div>
      <div class="st-modebar">${typePills}</div>
      <div class="st-modebar">${opPills}</div>
      <div class="dt-params">${_distRenderParams()}</div>
      <div class="dt-actions">
        <button class="st-btn st-btn-p" data-act="compute">Compute</button>
      </div>
      <div class="dt-result">
        ${res
          ? `<div class="dt-rlabel">${_escCalc(res.label)}</div>
             <div class="dt-rvalue">${Number.isFinite(res.value) ? (typeof calcFormatResult === 'function' ? calcFormatResult(res.value) : res.value) : '—'}</div>`
          : '<div class="st-empty">Choose a distribution and press Compute</div>'}
      </div>
    </div>`;
}

/** Wires input/button handlers for Distribution mode. */
function calcWireDist(){
  const panel = document.querySelector('#calc-p .calc-dist');
  if(!panel || panel._wired) return;
  panel._wired = true;

  panel.addEventListener('input', e => {
    const inp = e.target.closest('.dt-pinput');
    if(!inp) return;
    const key = inp.dataset.pkey;
    if(key) CALC_DIST_STATE.params[key] = inp.value;
    if(typeof scheduleAutosave === 'function') scheduleAutosave();
  });

  panel.addEventListener('click', e => {
    const btn = e.target.closest('[data-act]');
    if(!btn) return;
    const act = btn.dataset.act;
    if(act.startsWith('type-')){
      CALC_DIST_STATE.type = act.slice(5);
      // Reset op if the new type doesn't support the current one
      const ops = _distOpsFor(CALC_DIST_STATE.type).map(o => o.id);
      if(!ops.includes(CALC_DIST_STATE.op)) CALC_DIST_STATE.op = 'pdf';
      CALC_DIST_STATE.result = null;
      if(typeof scheduleAutosave === 'function') scheduleAutosave();
      calcRenderUI();
      return;
    }
    if(act.startsWith('op-')){
      CALC_DIST_STATE.op = act.slice(3);
      CALC_DIST_STATE.result = null;
      if(typeof scheduleAutosave === 'function') scheduleAutosave();
      calcRenderUI();
      return;
    }
    if(act === 'compute'){
      CALC_DIST_STATE.result = _distCompute();
      calcRenderUI();
      if(typeof scheduleAutosave === 'function') scheduleAutosave();
    }
  });
}

;
/* ==== src/js/features/calc/calc-table.js ==== */
/* features/calc/calc-table.js — Table mode (fx-8200 style)

   Tabulates a user-supplied real-valued expression f(x) over a range
   [start, end] with a constant step. Computed via the existing
   calcEvaluate() pipeline, so every feature supported in Calculate mode
   (functions, constants, variables other than x) is supported here too.
   Bound variable defaults to x but can be any single letter in
   CALC_STATE.vars (saved/restored around each row so table evaluation
   doesn't clobber user state).

   Output rows feed the grid and can be piped into Statistics mode's
   2-var data grid via the "Send to Stats" button — useful for fitting
   regression curves to a tabulated function. */

/** Factory for the Table state shape. Shared with reset/restore. */
function _calcTableDefaults(){
  return {
    expr:  'x^2',            // expression of the bound variable
    varN:  'x',              // bound variable name
    start: '-5',
    end:   '5',
    step:  '1',
    rows:  [],               // [{x:number, y:number|NaN, err:string|null}]
    error: null              // top-level error (e.g. bad bounds)
  };
}

const CALC_TABLE_STATE = _calcTableDefaults();

/** Fields persisted via the session snapshot. Shared with persistence.js
 *  so the save and restore paths can't drift when the state shape grows.
 *  Computed `rows` and `error` are excluded — they can be regenerated. */
const CALC_TABLE_PERSIST_FIELDS = ['expr','varN','start','end','step'];

/** Resets runtime Table state in place. */
function resetCalcTableState(){
  const d = _calcTableDefaults();
  CALC_TABLE_STATE.expr  = d.expr;
  CALC_TABLE_STATE.varN  = d.varN;
  CALC_TABLE_STATE.start = d.start;
  CALC_TABLE_STATE.end   = d.end;
  CALC_TABLE_STATE.step  = d.step;
  CALC_TABLE_STATE.rows  = d.rows;
  CALC_TABLE_STATE.error = d.error;
}

/** Evaluates the bounds/step strings via calcEvaluate so users can type
 *  expressions like pi or 2^10. Returns null on bad input. */
function _tableEvalNumber(s){
  if(typeof calcEvaluate !== 'function') return null;
  const r = calcEvaluate(String(s == null ? '' : s));
  return (r.ok && r.value != null && Number.isFinite(r.value)) ? r.value : null;
}

/** Builds the (x, f(x)) rows by binding the loop variable, evaluating
 *  the expression, and restoring the prior var value afterwards. Caps
 *  rows at 1000 to prevent UI stalls from accidental tiny steps. */
function calcTableCompute(){
  CALC_TABLE_STATE.rows  = [];
  CALC_TABLE_STATE.error = null;

  const name = String(CALC_TABLE_STATE.varN || 'x').trim() || 'x';
  // Tabulation requires a loop-variable slot — must be a single ASCII
  // letter (Ans is read-only, so anything multi-char is rejected even if
  // it somehow already existed in CALC_STATE.vars).
  if(!/^[A-Za-z]$/.test(name)){
    CALC_TABLE_STATE.error = 'Variable must be a single letter';
    return;
  }
  if(typeof CALC_STATE === 'undefined' ||
     !Object.prototype.hasOwnProperty.call(CALC_STATE.vars, name)){
    CALC_TABLE_STATE.error = 'Unknown variable: ' + name;
    return;
  }

  const start = _tableEvalNumber(CALC_TABLE_STATE.start);
  const end   = _tableEvalNumber(CALC_TABLE_STATE.end);
  const step  = _tableEvalNumber(CALC_TABLE_STATE.step);
  if(start == null || end == null || step == null){
    CALC_TABLE_STATE.error = 'Bad bounds or step';
    return;
  }
  if(step === 0){
    CALC_TABLE_STATE.error = 'Step cannot be zero';
    return;
  }
  // Infer direction automatically so `start > end` with a positive step
  // walks backwards instead of immediately terminating.
  const signedStep = (end < start) ? -Math.abs(step) : Math.abs(step);
  // Scale-aware epsilon used for both row counting and the final-row
  // snap. Needed because endpoint-aligned inputs like start=0, end=0.3,
  // step=0.1 produce 2.999...9 when divided, which Math.floor would
  // undercount to 2 and drop the intended final row at 0.3.
  const eps = Math.max(Math.abs(signedStep), 1) * 1e-9;
  const count = Math.floor((Math.abs(end - start) + eps) / Math.abs(step)) + 1;
  if(count > 1000){
    CALC_TABLE_STATE.error = 'Too many rows (' + count + ') — increase step';
    return;
  }

  const expr = String(CALC_TABLE_STATE.expr || '').trim();
  if(!expr){ CALC_TABLE_STATE.error = 'Empty expression'; return; }

  const saved = CALC_STATE.vars[name];
  try {
    for(let i = 0; i < count; i++){
      let x = start + i * signedStep;
      // Snap the final row to `end` when float drift put us within eps,
      // so displayed tables finish exactly where the user requested.
      if(i === count - 1 && Math.abs(x - end) < eps) x = end;
      CALC_STATE.vars[name] = x;
      const r = calcEvaluate(expr);
      CALC_TABLE_STATE.rows.push({
        x,
        y:   r.ok ? r.value : NaN,
        err: r.ok ? null    : (r.error || 'Err')
      });
    }
  } finally {
    CALC_STATE.vars[name] = saved;
  }
}

/** Copies the current table into Statistics mode as 2-var data, then
 *  navigates to Stats. Only finite (x,y) pairs are kept.
 *
 *  Recomputes the table before export so inputs edited since the last
 *  Generate press can't ship stale rows. If the recompute surfaces a
 *  bounds/expression error, the UI refreshes with that error rather
 *  than silently sending nothing. */
function calcTableSendToStats(){
  if(typeof CALC_STATS_STATE === 'undefined') return;
  calcTableCompute();
  if(CALC_TABLE_STATE.error){
    calcRenderUI();
    if(typeof showToast === 'function') showToast('Fix inputs first: ' + CALC_TABLE_STATE.error);
    return;
  }
  const pairs = CALC_TABLE_STATE.rows
    .filter(r => Number.isFinite(r.x) && Number.isFinite(r.y))
    .map(r => ({ x: String(r.x), y: String(r.y), freq: '1' }));
  if(!pairs.length){
    if(typeof showToast === 'function') showToast('No finite rows to send');
    return;
  }
  CALC_STATS_STATE.mode    = '2var';
  CALC_STATS_STATE.rows    = pairs;
  CALC_STATS_STATE.results = null;
  // Switch mode BEFORE scheduling autosave so the persisted CALC_STATE.mode
  // reflects where the user actually ended up, not the intermediate 'table'.
  CALC_STATE.mode = 'statistics';
  if(typeof calcRenderUI   === 'function') calcRenderUI();
  if(typeof scheduleAutosave === 'function') scheduleAutosave();
  if(typeof showToast      === 'function') showToast(`Sent ${pairs.length} rows to Stats`);
}

function _tableFmt(v){
  if(v == null || Number.isNaN(v)) return '—';
  if(typeof calcFormatResult === 'function') return calcFormatResult(v);
  return String(v);
}

function calcRenderTable(){
  const fs = (typeof CALC_STATE !== 'undefined' && CALC_STATE.fullscreen) ? ' calc-fs' : '';
  const rows = CALC_TABLE_STATE.rows;
  let body = '';
  if(CALC_TABLE_STATE.error){
    body = `<div class="st-empty" style="color:var(--err);">${_escCalc(CALC_TABLE_STATE.error)}</div>`;
  } else if(!rows.length){
    body = '<div class="st-empty">Enter expression and range, then press Generate</div>';
  } else {
    const trs = rows.map((r, i) => `
      <tr>
        <td>${i+1}</td>
        <td>${_tableFmt(r.x)}</td>
        <td>${r.err ? `<span style="color:var(--err);">${_escCalc(r.err)}</span>` : _tableFmt(r.y)}</td>
      </tr>`).join('');
    body = `
      <table>
        <thead><tr><th>#</th><th>${_escCalc(CALC_TABLE_STATE.varN)}</th><th>f(${_escCalc(CALC_TABLE_STATE.varN)})</th></tr></thead>
        <tbody>${trs}</tbody>
      </table>`;
  }

  const P = CALC_TABLE_STATE;
  return `
    <div class="calc-wrap calc-table${fs}">
      <div class="calc-hdr">
        <button class="calc-home-btn" data-hgl-action="home" title="Home"><span class="ms">apps</span></button>
        <span class="calc-brand hf">Table</span>
        <button class="calc-x" data-hgl-action="close" title="Close"><span class="ms">close</span></button>
      </div>
      <div class="dt-params" style="grid-template-columns:repeat(4,1fr);">
        <label class="dt-p" style="grid-column:span 4;">
          <span class="dt-plabel">f(${_escCalc(P.varN)}) =</span>
          <input class="dt-pinput tb-expr" data-tkey="expr" value="${_escCalc(P.expr)}">
        </label>
        <label class="dt-p">
          <span class="dt-plabel">var</span>
          <input class="dt-pinput" data-tkey="varN" value="${_escCalc(P.varN)}" maxlength="1" pattern="[A-Za-z]">
        </label>
        <label class="dt-p">
          <span class="dt-plabel">start</span>
          <input class="dt-pinput" data-tkey="start" value="${_escCalc(P.start)}">
        </label>
        <label class="dt-p">
          <span class="dt-plabel">end</span>
          <input class="dt-pinput" data-tkey="end" value="${_escCalc(P.end)}">
        </label>
        <label class="dt-p">
          <span class="dt-plabel">step</span>
          <input class="dt-pinput" data-tkey="step" value="${_escCalc(P.step)}">
        </label>
      </div>
      <div class="dt-actions" style="justify-content:space-between;">
        <button class="st-btn" data-act="send-stats" title="Send finite rows into Statistics 2-Var">→ Send to Stats</button>
        <button class="st-btn st-btn-p" data-act="compute">Generate</button>
      </div>
      <div class="st-table">${body}</div>
    </div>`;
}

function calcWireTable(){
  const panel = document.querySelector('#calc-p .calc-table');
  if(!panel || panel._wired) return;
  panel._wired = true;

  panel.addEventListener('input', e => {
    const inp = e.target.closest('.dt-pinput');
    if(!inp) return;
    const key = inp.dataset.tkey;
    if(key && Object.prototype.hasOwnProperty.call(CALC_TABLE_STATE, key)){
      CALC_TABLE_STATE[key] = inp.value;
      if(typeof scheduleAutosave === 'function') scheduleAutosave();
    }
  });

  panel.addEventListener('click', e => {
    const btn = e.target.closest('[data-act]');
    if(!btn) return;
    if(btn.dataset.act === 'compute'){
      calcTableCompute();
      calcRenderUI();
      if(typeof scheduleAutosave === 'function') scheduleAutosave();
    } else if(btn.dataset.act === 'send-stats'){
      calcTableSendToStats();
    }
  });
}

