/* ==== src/js/features/calc/calc-complex.js ==== */
/* features/calc/calc-complex.js — Complex arithmetic mode

   Dedicated shunting-yard evaluator for expressions over the complex
   numbers. Does NOT share calcEvaluate's RPN engine — that one operates
   on scalars and promoting every op to {re, im} would regress Calculate-
   mode performance. Instead this file ships a small self-contained
   parser specialized for complex values.

   Supports:
     - literals:   numeric (2, 3.5, 1e-3), pure imaginary (i, 2i, 3.5i)
     - binary ops: + − × ÷ ^ (real exponents only)
     - unary:      -x, conj(x)
     - functions:  abs, arg, re, im, sqrt, exp, ln, conj
     - constants:  pi, e, i
     - grouping:   ( )

   Result display toggles between rectangular (a+bi) and polar (r∠θ).
   Angle units follow CALC_STATE.angle (deg | rad). */

function _calcComplexDefaults(){
  return {
    input:  '(2+3i)*(1-i)',
    form:   'rect',          // 'rect' | 'polar'
    result: null              // { re, im, err } once computed
  };
}

const CALC_COMPLEX_STATE = _calcComplexDefaults();

/** Snapshot whitelist shared with persistence.js. `result` is excluded —
 *  it can be recomputed from `input` on demand. */
const CALC_COMPLEX_PERSIST_FIELDS = ['input','form'];

function resetCalcComplexState(){
  const d = _calcComplexDefaults();
  CALC_COMPLEX_STATE.input  = d.input;
  CALC_COMPLEX_STATE.form   = d.form;
  CALC_COMPLEX_STATE.result = d.result;
}

/* ── COMPLEX ARITHMETIC PRIMITIVES ─────────────────────────── */

function _cx(re, im){ return { re, im: im || 0 }; }
function _cxAdd(a, b){ return _cx(a.re + b.re, a.im + b.im); }
function _cxSub(a, b){ return _cx(a.re - b.re, a.im - b.im); }
function _cxMul(a, b){
  return _cx(a.re * b.re - a.im * b.im, a.re * b.im + a.im * b.re);
}
function _cxDiv(a, b){
  const d = b.re * b.re + b.im * b.im;
  if(d === 0) throw new Error('Division by zero');
  return _cx((a.re * b.re + a.im * b.im) / d,
             (a.im * b.re - a.re * b.im) / d);
}
function _cxNeg(a){ return _cx(-a.re, -a.im); }
function _cxAbs(a){ return Math.hypot(a.re, a.im); }
function _cxArgRad(a){ return Math.atan2(a.im, a.re); }
function _cxConj(a){ return _cx(a.re, -a.im); }
function _cxExp(a){
  const k = Math.exp(a.re);
  return _cx(k * Math.cos(a.im), k * Math.sin(a.im));
}
function _cxLn(a){
  const r = _cxAbs(a);
  if(r === 0) throw new Error('ln(0)');
  return _cx(Math.log(r), _cxArgRad(a));
}
function _cxSqrt(a){
  // Principal branch via half-angle
  const r = Math.sqrt(_cxAbs(a));
  const t = _cxArgRad(a) / 2;
  return _cx(r * Math.cos(t), r * Math.sin(t));
}
function _cxPowReal(a, n){
  // a^n for real n via polar form. General a^b would need _cxExp(_cxMul(b,_cxLn(a)))
  // but the parser restricts exponents to real literals for this release.
  if(!Number.isFinite(n)) throw new Error('Bad exponent');
  if(a.re === 0 && a.im === 0){
    if(n === 0) return _cx(1, 0);
    if(n < 0) throw new Error('0 raised to negative');
    return _cx(0, 0);
  }
  const r = Math.pow(_cxAbs(a), n);
  const t = _cxArgRad(a) * n;
  return _cx(r * Math.cos(t), r * Math.sin(t));
}

const _CX_FUNCTIONS = {
  abs:  a => _cx(_cxAbs(a), 0),
  arg:  a => {
    const rad = _cxArgRad(a);
    return _cx(CALC_STATE.angle === 'deg' ? rad * 180 / Math.PI : rad, 0);
  },
  re:   a => _cx(a.re, 0),
  im:   a => _cx(a.im, 0),
  conj: _cxConj,
  sqrt: _cxSqrt,
  exp:  _cxExp,
  ln:   _cxLn
};
const _CX_CONSTANTS = { pi: _cx(Math.PI, 0), e: _cx(Math.E, 0), i: _cx(0, 1) };

/* ── TOKENIZER ─────────────────────────────────────────────── */

function _cxTokenize(src){
  const tokens = [];
  let i = 0;
  while(i < src.length){
    const c = src[i];
    if(c === ' '){ i++; continue; }

    if(/[0-9.]/.test(c)){
      const m = src.slice(i).match(/^(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/);
      if(!m) throw new Error('Bad number near: ' + src.slice(i, i+4));
      const n = Number(m[0]);
      i += m[0].length;
      // Trailing 'i' → pure imaginary literal (3i, 2.5i, 1e-3i)
      if(src[i] === 'i' && !/[a-zA-Z0-9_]/.test(src[i+1] || '')){
        tokens.push({ type:'num', value: _cx(0, n) });
        i++;
      } else {
        tokens.push({ type:'num', value: _cx(n, 0) });
      }
      continue;
    }

    if(/[a-zA-Z_]/.test(c)){
      let j = i;
      while(j < src.length && /[a-zA-Z0-9_]/.test(src[j])) j++;
      const name = src.slice(i, j);
      tokens.push({ type:'ident', value: name });
      i = j; continue;
    }

    if('+-*/^(),'.indexOf(c) >= 0){
      tokens.push({ type:'op', value: c });
      i++; continue;
    }
    if(c === '×'){ tokens.push({type:'op', value:'*'}); i++; continue; }
    if(c === '÷'){ tokens.push({type:'op', value:'/'}); i++; continue; }
    if(c === '−'){ tokens.push({type:'op', value:'-'}); i++; continue; }

    throw new Error('Unexpected character: ' + c);
  }
  return tokens;
}

/* ── SHUNTING-YARD ─────────────────────────────────────────── */

const _CX_PREC = { '+':1, '-':1, '*':2, '/':2, 'u-':3, '^':4 };
const _CX_RIGHT = { '^':true, 'u-':true };

function _cxToRPN(tokens){
  const out = [];
  const stack = [];
  let prev = null;
  for(let i = 0; i < tokens.length; i++){
    const t = tokens[i];
    // Implicit multiplication: num/ident/) followed by num/ident/( inserts *
    if(prev){
      const leftIsVal = (prev.type === 'num' || prev.type === 'ident' ||
                        (prev.type === 'op' && prev.value === ')'));
      const rightIsVal = (t.type === 'num' || t.type === 'ident' ||
                         (t.type === 'op' && t.value === '('));
      // Skip when prev was a function call that just opened '('
      const prevIsFn = prev.type === 'ident' && Object.prototype.hasOwnProperty.call(_CX_FUNCTIONS, prev.value);
      if(leftIsVal && rightIsVal && !(prevIsFn && t.type === 'op' && t.value === '(')){
        while(stack.length){
          const top = stack[stack.length - 1];
          if(top.type === 'op' && top.value !== '(' &&
             (_CX_PREC[top.value] || 0) >= _CX_PREC['*']){
            out.push(stack.pop());
          } else break;
        }
        stack.push({ type:'op', value:'*' });
      }
    }

    if(t.type === 'num'){ out.push(t); prev = t; continue; }

    if(t.type === 'ident'){
      const isFn = Object.prototype.hasOwnProperty.call(_CX_FUNCTIONS, t.value);
      if(isFn && tokens[i+1] && tokens[i+1].type === 'op' && tokens[i+1].value === '('){
        stack.push({ type:'fn', value: t.value });
      } else {
        // constant or error deferred to eval
        out.push({ type:'var', value: t.value });
      }
      prev = t; continue;
    }

    if(t.type === 'op'){
      const op = t.value;
      if(op === '('){ stack.push(t); prev = t; continue; }
      if(op === ')'){
        while(stack.length && !(stack[stack.length-1].type === 'op' && stack[stack.length-1].value === '(')){
          out.push(stack.pop());
        }
        if(!stack.length) throw new Error('Mismatched parens');
        stack.pop();
        if(stack.length && stack[stack.length-1].type === 'fn') out.push(stack.pop());
        prev = t; continue;
      }
      if(op === ','){
        while(stack.length && !(stack[stack.length-1].type === 'op' && stack[stack.length-1].value === '(')){
          out.push(stack.pop());
        }
        prev = t; continue;
      }
      let actual = op;
      if(op === '-' && (!prev || (prev.type === 'op' && prev.value !== ')'))) actual = 'u-';
      // Unary minus is a prefix operator: push it directly without
      // draining higher-precedence ops first, so `2^-2` parses as
      // `2 ^ (-2)` instead of popping `^` before the RHS is emitted.
      if(actual === 'u-'){
        stack.push({ type:'op', value: actual });
        prev = t;
        continue;
      }
      while(stack.length){
        const top = stack[stack.length-1];
        if(top.type !== 'op' || top.value === '(') break;
        const tp = _CX_PREC[top.value] || 0;
        const cp = _CX_PREC[actual] || 0;
        if(tp > cp || (tp === cp && !_CX_RIGHT[actual])) out.push(stack.pop());
        else break;
      }
      stack.push({ type:'op', value: actual });
      prev = t; continue;
    }
  }
  while(stack.length){
    const top = stack.pop();
    if(top.type === 'op' && (top.value === '(' || top.value === ')')) throw new Error('Mismatched parens');
    out.push(top);
  }
  return out;
}

/* ── EVALUATOR ─────────────────────────────────────────────── */

function _cxEvalRPN(rpn){
  const s = [];
  for(const t of rpn){
    if(t.type === 'num'){ s.push(t.value); continue; }
    if(t.type === 'var'){
      if(Object.prototype.hasOwnProperty.call(_CX_CONSTANTS, t.value)){ s.push(_CX_CONSTANTS[t.value]); continue; }
      throw new Error('Unknown name: ' + t.value);
    }
    if(t.type === 'fn'){
      const fn = _CX_FUNCTIONS[t.value];
      if(!fn) throw new Error('Unknown function: ' + t.value);
      if(!s.length) throw new Error('Bad call to ' + t.value);
      s.push(fn(s.pop()));
      continue;
    }
    if(t.type === 'op'){
      const op = t.value;
      if(op === 'u-'){
        if(!s.length) throw new Error('Bad unary -');
        s.push(_cxNeg(s.pop())); continue;
      }
      if(s.length < 2) throw new Error('Bad op ' + op);
      const b = s.pop(), a = s.pop();
      switch(op){
        case '+': s.push(_cxAdd(a, b)); break;
        case '-': s.push(_cxSub(a, b)); break;
        case '*': s.push(_cxMul(a, b)); break;
        case '/': s.push(_cxDiv(a, b)); break;
        case '^':
          if(b.im !== 0) throw new Error('Complex exponent not supported');
          s.push(_cxPowReal(a, b.re));
          break;
        default: throw new Error('Bad op: ' + op);
      }
    }
  }
  if(s.length !== 1) throw new Error('Malformed expression');
  return s[0];
}

/** Public API — parse, evaluate, return {ok, value:{re,im}, error}. */
function calcEvaluateComplex(src){
  try {
    const tokens = _cxTokenize(String(src || ''));
    const rpn    = _cxToRPN(tokens);
    const v      = _cxEvalRPN(rpn);
    if(!Number.isFinite(v.re) || !Number.isFinite(v.im)){
      return { ok:false, value:null, error:'Non-finite result' };
    }
    return { ok:true, value:v, error:null };
  } catch(e){
    return { ok:false, value:null, error: e.message };
  }
}

/* ── FORMATTING ────────────────────────────────────────────── */

function _cxFmtNum(n){
  if(typeof calcFormatResult === 'function') return calcFormatResult(n);
  return String(n);
}

function _cxFormatRect(v){
  if(!v) return '—';
  const re = v.re, im = v.im;
  const reStr = _cxFmtNum(re);
  if(im === 0) return reStr;
  const imAbs  = Math.abs(im);
  const imStr  = imAbs === 1 ? 'i' : _cxFmtNum(imAbs) + 'i';
  if(re === 0) return (im < 0 ? '-' : '') + imStr;
  return reStr + (im < 0 ? ' − ' : ' + ') + imStr;
}

function _cxFormatPolar(v){
  if(!v) return '—';
  const r = Math.hypot(v.re, v.im);
  let theta = Math.atan2(v.im, v.re);
  if(CALC_STATE.angle === 'deg') theta = theta * 180 / Math.PI;
  return _cxFmtNum(r) + ' ∠ ' + _cxFmtNum(theta) + (CALC_STATE.angle === 'deg' ? '°' : ' rad');
}

/* ── UI ────────────────────────────────────────────────────── */

function calcRenderComplex(){
  const fs = (typeof CALC_STATE !== 'undefined' && CALC_STATE.fullscreen) ? ' calc-fs' : '';
  const S = CALC_COMPLEX_STATE;
  const res = S.result;
  let out = '<div class="st-empty">Enter a complex expression and press Evaluate</div>';
  if(res){
    if(res.err){
      out = `<div class="st-empty" style="color:var(--err);">${_escCalc(res.err)}</div>`;
    } else {
      // Render only the selected form so the a+bi / r∠θ pill toggle
      // actually swaps the output instead of just re-styling a row.
      const isPolar = S.form === 'polar';
      const label   = isPolar ? 'Polar' : 'Rect';
      const value   = isPolar ? _cxFormatPolar(res) : _cxFormatRect(res);
      out = `
        <div class="cx-results">
          <div class="cx-row on"><span class="cx-rk">${label}</span><span class="cx-rv">${_escCalc(value)}</span></div>
        </div>`;
    }
  }

  return `
    <div class="calc-wrap calc-complex${fs}">
      <div class="calc-hdr">
        <button class="calc-home-btn" data-hgl-action="home" title="Home"><span class="ms">apps</span></button>
        <span class="calc-brand hf">Complex</span>
        <button class="calc-x" data-hgl-action="close" title="Close"><span class="ms">close</span></button>
      </div>
      <div class="st-modebar">
        <button class="st-pill${S.form==='rect'?' on':''}"  data-act="form-rect">a + bi</button>
        <button class="st-pill${S.form==='polar'?' on':''}" data-act="form-polar">r ∠ θ</button>
        <div style="flex:1"></div>
        <span style="font-size:10px;color:var(--fg3);letter-spacing:.08em;">fns: abs arg re im conj sqrt exp ln</span>
      </div>
      <div class="dt-params" style="grid-template-columns:1fr;">
        <label class="dt-p">
          <span class="dt-plabel">expression</span>
          <input class="dt-pinput cx-expr" data-ckey="input" value="${_escCalc(S.input)}">
        </label>
      </div>
      <div class="dt-actions">
        <button class="st-btn st-btn-p" data-act="evaluate">Evaluate</button>
      </div>
      <div class="dt-result">${out}</div>
    </div>`;
}

function calcWireComplex(){
  const panel = document.querySelector('#calc-p .calc-complex');
  if(!panel || panel._wired) return;
  panel._wired = true;

  panel.addEventListener('input', e => {
    const inp = e.target.closest('.dt-pinput');
    if(!inp) return;
    if(inp.dataset.ckey === 'input'){
      CALC_COMPLEX_STATE.input = inp.value;
      if(typeof scheduleAutosave === 'function') scheduleAutosave();
    }
  });

  panel.addEventListener('click', e => {
    const btn = e.target.closest('[data-act]');
    if(!btn) return;
    const act = btn.dataset.act;
    if(act === 'form-rect' || act === 'form-polar'){
      CALC_COMPLEX_STATE.form = act === 'form-polar' ? 'polar' : 'rect';
      if(typeof scheduleAutosave === 'function') scheduleAutosave();
      calcRenderUI();
      return;
    }
    if(act === 'evaluate'){
      const r = calcEvaluateComplex(CALC_COMPLEX_STATE.input);
      CALC_COMPLEX_STATE.result = r.ok
        ? { re: r.value.re, im: r.value.im, err: null }
        : { re: NaN, im: NaN, err: r.error };
      if(typeof scheduleAutosave === 'function') scheduleAutosave();
      calcRenderUI();
    }
  });
}

