/* Module-level search query state — survives panel re-renders
 * (e.g. an unrelated calcRenderUI triggered while catalog is
 * open). Reset to '' on panel close + on tap-to-insert. The
 * value is hydrated into the search input's `value` attribute
 * during render, and row visibility re-derives from it during
 * render so closing/reopening preserves filter state if we
 * later decide to keep query across opens (today we wipe). */
let _calcCatalogQuery = '';

/** Public setter so the inline `oninput` handler in render can
 *  push the query without grabbing module-internal state. */
function _calcCatalogSetQuery(q){
  _calcCatalogQuery = (typeof q === 'string') ? q.toLowerCase().trim() : '';
}

/** Search-key for substring match. Lowercased concat of label,
 *  syntax, and category — typing "trig" matches all three trig
 *  categories; typing "comb" finds Combinations; typing "log"
 *  matches Logarithmic, Common Log, Natural Log, and Log with
 *  base. Computed at render time so the data-attribute carries
 *  the precomputed key for the search handler. */
function _calcCatalogSearchKey(entry){
  return (entry.label + ' ' + entry.syntax + ' ' + entry.category).toLowerCase();
}

/** Renders the CATALOG panel body. Returned as the keypadBody
 *  when CALC_STATE.activePanel === 'catalog'. */
function _calcRenderCatalogPanel(/* S */){
  const q = _calcCatalogQuery;
  let visibleCount = 0;
  let rowsHtml = '';
  for(const entry of CALC_CATALOG){
    const key = _calcCatalogSearchKey(entry);
    const matches = !q || key.indexOf(q) !== -1;
    if(matches) visibleCount++;
    const hidden = matches ? '' : ' style="display:none;"';
    const hintAttr = entry.hint ? ` title="${_escCalc(entry.hint)}"` : '';
    rowsHtml += `
      <button type="button" class="ck calc-v2-catalog-row" data-act="v2-catalog-select" data-catalog-id="${_escCalc(entry.id)}" data-catalog-search-key="${_escCalc(key)}"${hintAttr}${hidden}>
        <span class="calc-v2-catalog-label">${_escCalc(entry.label)}</span>
        <span class="calc-v2-catalog-syntax">${_escCalc(entry.syntax)}</span>
        <span class="calc-v2-catalog-category">${_escCalc(entry.category)}</span>
      </button>`;
  }
  const emptyDisplay = (visibleCount === 0) ? '' : ' style="display:none;"';
  /* The search input fires oninput which calls
   * _calcCatalogOnSearch — that toggles row visibility via
   * inline display style without triggering calcRenderUI, so
   * the input keeps focus through every keystroke. The render
   * path only fires on explicit panel-state changes (open /
   * close / tap-to-insert / external calcRenderUI). */
  return `
    <div class="calc-v2-panel calc-v2-catalog-panel">
      <div class="calc-v2-panel-hdr">
        <span class="calc-v2-panel-title">Catalog</span>
        <button type="button" class="ck calc-v2-act calc-v2-act--ghost calc-v2-panel-close" data-act="v2-catalog" aria-label="Close catalog panel">×</button>
      </div>
      <input type="text" class="calc-v2-catalog-search" placeholder="Search functions…" value="${_escCalc(q)}" autocomplete="off" spellcheck="false" aria-label="Search catalog"  />
      <div class="calc-v2-catalog-list">${rowsHtml}</div>
      <div class="calc-v2-catalog-empty"${emptyDisplay}>No matches</div>
    </div>`;
}

/** Inline oninput handler — toggles row visibility via DOM
 *  mutation (no re-render) so the input keeps focus through
 *  every keystroke. Match against data-catalog-search-key
 *  precomputed at render time. */
function _calcCatalogOnSearch(e){
  const q = (e && e.target ? e.target.value : '').toLowerCase().trim();
  _calcCatalogSetQuery(q);
  const rows = document.querySelectorAll('#calc-p .calc-v2-catalog-row');
  let visible = 0;
  rows.forEach(row => {
    const key = row.dataset.catalogSearchKey || '';
    const match = !q || key.indexOf(q) !== -1;
    row.style.display = match ? '' : 'none';
    if(match) visible++;
  });
  const empty = document.querySelector('#calc-p .calc-v2-catalog-empty');
  if(empty) empty.style.display = (visible === 0) ? '' : 'none';
}

/** Tap-to-insert dispatcher. Routes through the same helpers
 *  the keypad uses, then closes the panel and demotes any
 *  fresh-result display. Called from _calcV2HandleAct's
 *  v2-catalog-select branch with the entry's id from
 *  data-catalog-id. */
function _calcCatalogHandleSelect(id){
  if(typeof id !== 'string' || !id) return;
  const entry = CALC_CATALOG.find(e => e.id === id);
  if(!entry) return;
  if(entry.kind === 'fn'){
    if(typeof calcInputInsertString === 'function') calcInputInsertString(entry.insert + '(');
  } else if(entry.kind === 'tmpl'){
    if(typeof calcInputInsertTemplate === 'function') calcInputInsertTemplate(entry.insert);
  } else if(entry.kind === 'ins'){
    if(typeof calcInputInsertString === 'function') calcInputInsertString(entry.insert);
  } else {
    return; // unknown kind — guard
  }
  if(typeof _afterInput === 'function') _afterInput(true);
  if(typeof CALC_STATE !== 'undefined') CALC_STATE.activePanel = null;
  _calcCatalogSetQuery('');
  if(typeof calcRenderUI === 'function') calcRenderUI();
  if(typeof _calcAutosave === 'function') _calcAutosave();
}




